window.DEFAULT_TRIPS = [{"id":"trip_1793202088746","name":"加拿大班夫洛磯山脈公路巡禮🇨🇦","locationName":"Canada 🍁","lat":51.1784,"lng":-115.5708,"minDays":7,"maxDays":10,"budget":"$$","costEstimate":"~NT$75,000 - 120,000 /人","seasons":["summer","autumn","winter"],"visited":false,"tags":["#班夫國家公園","#露易絲湖","#冰原大道","#洛磯山脈","#城堡飯店"],"description":"自駕世界最美公路冰原大道，在翡翠般碧綠的露易絲湖划獨木舟，夜宿百年溫泉城堡飯店仰望無垠星空與雪山。","itinerary":{"summary":"為 Seb 與 Lynn 量身打造的洛磯山脈漫旅，以緩慢步調依偎於雪山湖泊之間，在晨光咖啡與落日餘暉中私奔於楓紅與冰川交織的浪漫詩篇。","targetDays":9,"pace":"relaxed","days":[{"day":1,"theme":"啟程・飛越太平洋抵達卡加利 ✈️","morning":"搭乘長榮航空由桃園機場直飛溫哥華，轉機飛往洛磯山脈大門卡加利（Calgary），在雲端調整時差。","afternoon":"抵達卡加利國際機場，取妥舒適的自駕休旅車，入住市區典雅的 boutique hotel 稍作梳洗休息。","evening":"漫步於卡加利市中心的 Stephen Avenue Walk，在百年紅磚街屋的燈光下享用溫馨的迎賓晚餐。","coupleHighlight":"在異國微涼的夜風中，牽著手分享一杯熱可可，慶祝兩人專屬的洛磯山脈假期正式展開 ☕️"},{"day":2,"theme":"初見洛磯山・班夫小鎮漫步 🏔️","morning":"睡到自然醒，享用豐盛早午餐後，驅車沿著 1 號公路緩緩駛入班夫國家公園，沿途欣賞壯麗山景。","afternoon":"入住班夫鎮上的 Fairmont Banff Springs 城堡飯店，漫步於 Banff Avenue 挑選精緻的加拿大手工紀念品。","evening":"造訪人氣手沖咖啡館 Evelyn's Coffee Bar 歇腳，享受窗外被群山環繞的寧靜時刻。","coupleHighlight":"黃昏時分在 Bow River Bridge 河畔並肩散步，看夕陽為靈峰（Cascade Mountain）染上一抹金黃 🍂"},{"day":3,"theme":"仙境藍寶石・露易絲湖與冰川倒影 🛶","morning":"早晨不疾不徐地享用飯店早餐，驅車前往被譽為「洛磯山脈藍寶石」的露易絲湖（Lake Louise）。","afternoon":"租借一艘紅色木造獨木舟，兩人合力在平滑如鏡的冰川湖面上輕輕滑行，被巨大冰川與蒼鬱森林環抱。","evening":"坐在著名的 Fairmont Chateau Lake Louise 窗旁座位，一邊品嚐下午茶，一邊凝望窗外漸漸暗去的湖光山色。","coupleHighlight":"在湖畔的石凳上依偎著，靜靜等待遊客散去後的湖面恢復極致的寧靜與倒影 🌲"},{"day":4,"theme":"絕美秘境・夢蓮湖的十峰倒影 📸","morning":"清晨搭乘專屬接駁車前往夢蓮湖（Moraine Lake），避開人潮，獨佔世界級的「十峰山」日出景致。","afternoon":"午後漫步於約翰斯頓峽谷（Johnston Canyon），沿著平緩的架空木棧道尋訪隱密清澈的墨汁壺（Ink Pots）。","evening":"返回班夫小鎮，在著名的 Bison Restaurant 享用當地永續食材烹調的慢食晚餐。","coupleHighlight":"在峽谷瀑布旁的小橋上，交換一個只屬於彼此的輕吻，聆聽潺潺溪流與風動松濤 💧"},{"day":5,"theme":"雲端之上・硫磺山溫泉與纜車之旅 🚠","morning":"睡到日頭高照，隨後搭乘 Banff Gondola 班夫纜車緩緩升空，在 360 度觀景台俯瞰六條壯麗山脈。","afternoon":"午後前往 Banff Upper Hot Springs，在露天天然溫泉中浸泡，任由微涼山風吹拂臉龐。","evening":"在小鎮上的 Park Distillery 餐廳，品嚐在地釀造的精釀烈酒與柴火烤雞，感受木質調的溫馨氛圍。","coupleHighlight":"溫泉池畔熱氣蒸騰中，十指緊扣，感受冰火交融的極致放鬆與浪漫 🛁"},{"day":6,"theme":"冰原大道・世界最美公路的浪漫巡禮 🛣️","morning":"緩慢打包行李，展開此行最高潮的「冰原大道」（Icefields Parkway），沿途隨興停靠無名冰川與翠綠湖泊。","afternoon":"駐足於 Peyto Lake 佩托湖，從觀景台俯望如神祕狼頭造型的耀眼土耳其藍湖水。","evening":"入住冰原大道上的經典度假木屋（如 The Crossing 或賈斯珀區特色Lodge），遠離塵囂。","coupleHighlight":"深夜在完全無光害的高山木屋陽台一起抬頭仰望滿天星河與銀河，許下浪漫誓言 ✨"},{"day":7,"theme":"冰川巨獸・哥倫比亞冰原的純白震撼 🧊","morning":"前往哥倫比亞冰原（Columbia Icefield），搭乘巨型雪車（Ice Explorer）踏上萬年古老的阿薩巴斯卡冰川。","afternoon":"前往 Glacier Skywalk 冰川天空步道，在透明玻璃橋面上懸空俯瞰深邃的森瓦普塔河谷。","evening":"抵達賈斯珀國家公園（Jasper National Park），入住充滿山林野趣的 Fairmont Jasper Park Lodge。","coupleHighlight":"在冰川上用純淨的千年冰雪輕觸對方的臉頰，留下最清涼純粹的甜蜜笑聲 ❄️"},{"day":8,"theme":"森林與靈湖・賈斯珀的慵懶時光 🌲","morning":"在翠綠環繞的精靈湖（Spirit Island / Maligne Lake）搭乘遊船，尋找明信片中經典的孤島孤樹景致。","afternoon":"返回賈斯珀鎮上的 De'd Dog Café 或 Wild Mountain 慢步調享用午餐與精品咖啡。","evening":"造訪 Pyramid Lake 金字塔湖，夕陽將金字塔山（Pyramid Mountain）染成浪漫的粉紅色。","coupleHighlight":"坐在金字塔湖畔的紅色木椅上，披著同一條喀什米爾圍巾，靜靜看日落沒入山巔 🌅"},{"day":9,"theme":"珍重再見・帶著滿山回憶賦歸 🍁","morning":"享用最後一頓悠閒的加拿大楓糖鬆餅早餐，隨後開車沿著景色優美的黃頭高速公路（Yellowhead Hwy）返回卡加利。","afternoon":"在卡加利市區最後巡禮，於CrossIron Mills採購精緻伴手禮（如煙燻鮭魚與亞伯達牛肉乾），前往機場還車。","evening":"搭乘班機滿載著洛磯山脈的純淨芬多精與永恆回憶，踏上歸途返抵台灣。","coupleHighlight":"在飛機起飛升空時，頭靠著彼此的肩膀，翻閱相機裡這9天累積的甜蜜合照 ✈️"}],"mustTryFoods":["Alberta AAA Grade Ribeye Steak (頂級亞伯達肋眼牛排)","BeaverTails Canadian Pastry (經典海狸尾酥餅)","Banff Local Craft Beer & Spirits (班夫在地精釀啤酒)","Fresh Atlantic Salmon & Maple Glazed Dishes (楓糖烤鮭魚)"],"tips":"1. 洛磯山脈日夜溫差極大，即使夏季也務必採洋蔥式穿法並攜帶防風保暖外套；2. 露易絲湖與夢蓮湖停車位極為難求，強烈建議提前預訂 Parks Canada 官方接駁車（Shuttle）；3. 台灣旅客前往加拿大需事先申辦 eTA（電子旅行證），建議出發前一個月完成申請。","generatedAt":1793468244301,"model":"gemini-3.5-flash-lite"}},{"id":"trip_1793200447689","name":"高雄駁二文創港灣與旗津夕陽行","locationName":"Kaohsiung, Taiwan","lat":22.6163,"lng":120.3358,"minDays":2,"maxDays":4,"budget":"$","costEstimate":"~NT$4,000 - 8,000 /人","seasons":["all"],"visited":false,"tags":["#駁二藝術特區","#大港橋旋轉","#旗津夕陽","#六合夜市","#愛河漫遊"],"description":"午後散步於大港橋與駁二藝術特區感受海港微風，搭渡輪前往旗津看橘紅落日沉入大海，夜晚在愛河畔聽爵士小酌。","itinerary":{"summary":"為 Seb 與 Lynn 量身打造的高雄港灣漫遊，以緩慢的步調穿梭於駁二的工業老倉與旗津的金色海浪間，在無人的海景咖啡館與私房夕陽下，讓愛情隨港都的海風慢慢升溫。 🌊","targetDays":3,"pace":"relaxed","days":[{"day":1,"theme":"老倉文創與倉庫裡的微光下午茶 ☕","morning":"十點慵懶醒來，搭乘輕軌至大義站，漫步於綠意盎然的駁二大義倉庫群，牽手穿梭在舊鐵道改建的藝術廊道與獨立書店。 🌿","afternoon":"造訪藏身紅磚倉庫內的「in Our Time 倉庫」，點一杯手沖咖啡與肉桂捲，坐在靠窗位子聽老式黑膠唱片流瀉出的慵懶爵士樂。 🎶","evening":"散步至棧貳庫（KW2），挑選一間戶外海景餐酒館，享用在地海鮮晚餐，佐以眼前停泊著豪華遊艇的漸層夕陽港景。 🍷","coupleHighlight":"在棧貳庫純白旋轉木馬前，趁著華燈初上的魔幻時刻，留下兩人緊緊相依的浪漫光影。 🎠"},{"day":2,"theme":"渡輪海風與旗津半島的金色日落 🌅","morning":"睡到自然醒，悠閒享用早午餐後，從鼓山渡輪站搭乘渡輪前往旗津，在甲板上並肩迎著鹹鹹的海風，看高雄港的壯闊天際線。 ⛴️","afternoon":"租一台雙人協力車，騎過綠意盎然的旗津隧道，直達隱蔽的私房沙灘，赤腳踩在細軟的沙上，任由浪花輕拂腳踝。 🌊","evening":"登上旗津燈塔旁的觀景台，俯瞰整個港灣點燈的璀璨夜景，隨後漫步至旗津老街品嚐炭烤小卷。 🦑","coupleHighlight":"在旗津星空隧道出口的礁岩旁，背對夕陽沉入海平面的壯麗剪影，共享一顆剛買的古早味叭噗冰淇淋。 🍦"},{"day":3,"theme":"高空海景與愛河畔的浪漫告別 🥂","morning":"睡個飽覺後退房，前往高雄流行音樂中心，欣賞如珊瑚般流線型的絕美建築，在海音館戶外露台遠望大港橋的純白身影。 🏛️","afternoon":"搭乘計程車直上高雄最高地標 85 大樓周邊的高空景觀咖啡廳，居高臨下俯瞰整個高雄港灣與棋盤式市景，享受兩人的午后私密時光。 ☕","evening":"漫步至愛河畔的「高雄愛河愛之船」搭乘太陽能愛之船，伴隨岸邊街頭藝人的薩克斯風演奏，為這趟旅程劃下最溫柔的句點。 🎻","coupleHighlight":"在愛河漫步的微涼夜色中，輕輕依偎著彼此，互訴這三天裡最捨不得的一刻。 ✨"}],"mustTryFoods":["老江紅茶牛奶的招牌紅茶牛奶與火腿蛋吐司","棧貳庫職人手作拿鐵與肉桂捲","旗津在地碳烤小卷與新鮮海產粥","鹽埕區七賢三路老字號冬瓜檸檬愛玉"],"tips":"建議使用悠遊卡或一卡通暢遊高雄捷運與輕軌，省去購票時間；旗津租借雙人電動協力車前請先確認電量與煞車狀況；傍晚在旗津看夕陽時建議攜帶薄外套以防海風較大。","generatedAt":1793468242139,"model":"gemini-3.5-flash-lite"}},{"id":"trip_hokkaido","name":"北海道粉雪與小樽運河夢幻之旅","locationName":"Hokkaido, Japan","lat":43.0642,"lng":141.3469,"minDays":6,"maxDays":8,"budget":"$$","costEstimate":"~NT$45,000 - 68,000 /人","seasons":["winter","summer"],"visited":false,"tags":["#粉雪滑雪","#小樽運河","#雪見溫泉","#帝王蟹","#富良野薰衣草"],"description":"漫步小樽運河瓦斯燈下的雪景，在二世谷體驗世界級粉雪滑雪與露天雪見溫泉，夏季則有富良野盛開的薰衣草花田。","itinerary":{"summary":"專為Seb與Lynn打造的雪國浪漫詩篇，以緩慢優雅的步伐漫步於浪漫小樽與函館浪漫夜景，在溫泉與純白雪景中緊緊依偎。❄️✨","targetDays":6,"pace":"relaxed","days":[{"day":1,"theme":"初雪相遇・浪漫小樽運河漫步 🕯️","morning":"搭乘班機由台灣出發抵達新千歲機場，搭乘JR快速列車前往浪漫小樽，入住運河旁的古典設計旅店，慵懶享用迎賓熱可可。","afternoon":"午後漫步於雪花纷飛的小樽運河畔，手牽手走進「北一硝子三號館」，在6盞煤油燈映照的浪漫咖啡廳裡品嚐濃郁抹茶百匯。","evening":"在百年石造倉庫改建的「LeTAO小樽洋菓子舖本店」頂樓展望台眺望雪景，隨後享用頂級北海道爐端燒晚餐。","coupleHighlight":"在昏黃煤油燈光的浪漫Café裡，互相餵食一口綿密的雙層乳酪蛋糕 🍰"},{"day":2,"theme":"音樂盒與銀白童話・札幌漫步 🎶","morning":"睡到自然醒，前往「小樽音樂盒堂本館」，在滿室清脆的音樂聲中，挑選一個專屬於兩人的雪花音樂盒。","afternoon":"午後乘車返回札幌，入住大通公園附近的溫馨設計飯店，漫步至札幌市時計台與赤れんが庁舎感受復古歐風雪景。","evening":"前往貲之小路巷弄內的預約制湯咖哩名店「Suage+」，品嚐暖胃的碳烤雞腿湯咖哩，隨後登上札幌電視塔俯瞰閃爍的雪中燈海。","coupleHighlight":"在飘着雪花的大通公園長椅上，共用一條喀什米爾圍巾取暖 🧣"},{"day":3,"theme":"雪之精靈・旭山動物園與溫泉鄉 🐧","morning":"慵懶享用飯店早餐後，搭乘專車前往旭川，午後抵達人氣極高的「旭山動物園」，觀賞可愛的企鵝雪中散步。","afternoon":"離開動物園，轉乘專車前往浪漫的溫泉勝地層雲峽，入住隱密奢華的溫泉旅館，換上舒適的日式浴衣。","evening":"泡入被冰雪環繞的露天風呂溫泉中，欣賞滿天星斗與落雪交織的絕景，洗去旅途的疲憊。","coupleHighlight":"在霧氣蒸騰的雪中露天溫泉裡，遞上一杯冰涼的清酒乾杯 🍶"},{"day":4,"theme":"漫步雲端・美瑛雪原與浪漫之丘 🌲","morning":"享受豐盛的日式懷石早餐，隨後包車展開美瑛白金青池與白鬚瀑布的冬日雪景巡禮，捕捉枯木與白雪的絕美構圖。","afternoon":"造訪人煙稀少的「聖誕樹之木」，在孤立的大樹旁靜靜欣賞夕陽將雪地染成柔和的粉紫色。","evening":"返回旭川市區，在在地人推薦的「大黑屋」享用香氣四溢的成吉思汗烤羊肉與現榨生啤酒。","coupleHighlight":"在夕陽染粉的美瑛雪原孤樹旁，緊緊擁抱留下剪影合照 📸"},{"day":5,"theme":"函館百萬夜景・元町異國風情 纜車燈火 🚠","morning":"搭乘特急列車南下函館，沿途欣賞海天一色的冬日海岸線，入住元町山手歐風小旅館。","afternoon":"午後漫步於元町區的斜坡道，欣賞雪中西洋歷史建築，隨後走進「六花亭五稜郭店」二樓的玻璃屋咖啡座享用甜點。","evening":"搭乘「函館山纜車」登上山頂，在浪漫的觀景台欣賞被譽為世界三大夜景之一、宛如珠寶盒般的閃爍雪景。","coupleHighlight":"在函館山寒風中緊靠彼此，透過相機鏡頭尋找心型的夜景燈光 🌃"},{"day":6,"theme":"晨光朝市・滿載甜蜜回憶賦歸 🦀","morning":"睡個飽覺後，悠閒步行至「函館朝市」，品嚐奢侈的現剖海膽與炙燒干貝海鮮丼作為早午餐。","afternoon":"在函館金森紅磚倉庫選購精緻的伴手禮與手作紀念品，隨後專車前往函館機場，搭機返回溫暖的台灣。","evening":"帶著相機裡滿滿的雪景回憶與彼此的笑聲，平安降落桃園機場，結束浪漫的北海道之旅。","coupleHighlight":"在機場登機口前，交換彼此這趟旅程寫下的明信片與感謝 💌"}],"mustTryFoods":["LeTAO 雙層乳酪蛋糕 (Fromage Double)","Suage+ 炭烤雞腿湯咖哩","旭川大黑屋 成吉思汗烤羊肉","函館朝市 現剖新鮮海膽干貝丼"],"tips":"1. 建議提前三個月預訂札幌至旭川的觀光專車與溫泉旅館，冬日一房難求。2. 台灣旅客必備防滑雪靴與觸控式保暖手套，方便隨時拍照。3. 跨城市移動建議購買JR北海道鐵路周遊券（4日或5日券）最為經濟便利。","generatedAt":1793467891081,"model":"gemini-3.5-flash-lite"}},{"id":"trip_switzerland","name":"瑞士阿爾卑斯與少女峰冰川火車","locationName":"Interlaken & Zermatt, Switzerland","lat":46.6863,"lng":7.8632,"minDays":8,"maxDays":12,"budget":"$$","costEstimate":"~NT$95,000 - 150,000 /人","seasons":["summer","winter"],"visited":false,"tags":["#阿爾卑斯山","#少女峰","#冰川快車","#馬特洪峰","#圖恩湖"],"description":"搭乘全景景觀齒軌列車穿越雪山冰川，遠眺巍峨馬特洪峰倒影，在湖光山色的童話木屋小鎮品嚐正宗起司火鍋。","itinerary":{"summary":"為 Seb 與 Lynn 打造的阿爾卑斯浪漫慢旅，搭乘冰川列車與少女峰齒軌列車，在雪山環抱與湖光山色中，享受極致的私密與奢華閒適。 🏔️🚂","targetDays":10,"pace":"relaxed","days":[{"day":1,"theme":"啟程・飛越亞歐大陸抵達蘇黎世 ✈️","morning":"搭乘長榮航空或國泰航空豪華班機，在機上享用醇厚咖啡，並肩欣賞窗外雲海與日出 ☕☁️","afternoon":"抵達蘇黎世機場，轉乘瑞士聯邦鐵路（SBB）景觀火車前往因特拉肯（Interlaken），沿途欣賞如詩如畫的湖泊與翠綠山谷 🚆✨","evening":"入住因特拉肯面山浪漫度假酒店，漫步於 Höhematte 公園，遠眺夕陽餘暉灑在少女峰山巔的金色奇景 🏔️🌅","coupleHighlight":"在百年溫泉飯店的陽台，共啜一杯瑞士熱可可，呼吸阿爾卑斯山的第一口冷冽微風 ☕❄️"},{"day":2,"theme":"圖恩湖浪漫雙人遊船・漫步童話小鎮 ⛵","morning":"睡到自然醒，享用豐富的瑞士早午餐，隨後漫步至因特拉肯東站搭乘圖恩湖（Lake Thun）復古蒸汽遊船 ⛴️🥐","afternoon":"於施皮茲（Spiez）下船，漫步於被譽為「瑞士最美小鎮」的葡萄園小徑，感受湖水碧綠如玉的寧靜 🍇💧","evening":"在施皮茲湖畔景觀餐廳享用鮮嫩的白酒清蒸湖魚晚餐，配上一杯當地產的產區白酒 🐟🍷","coupleHighlight":"在城堡花園的長椅上並肩而坐，背對著雪山與古堡，用拍立得留下兩人相視微笑的瞬間 📸🌸"},{"day":3,"theme":"少女峰冰川天堂・雲端上的甜蜜漫步 ❄️","morning":"慵懶地用過早餐，搭乘全新 Eiger Express 三索纜車直達艾格冰川站，轉乘少女峰鐵路登頂歐洲之巔 🏔️🚠","afternoon":"探索冰川宮殿（Ice Palace），在斯芬克斯觀景台牽手俯瞰阿萊奇冰河（Aletsch Glacier）的壯闊冰川奇景 🧊✨","evening":"回到因特拉肯市區，在百年木屋餐廳享用濃郁道地的瑞士起司鍋（Fondue） 🫕🕯️","coupleHighlight":"在海拔 3454 公尺的雪地郵局，一起寫一張明信片寄回台灣，蓋上專屬的少女峰登頂紀念郵戳 💌📮"},{"day":4,"theme":"勞特布魯嫩・瀑布鎮的詩意午後 🌊","morning":"睡個飽覺後出發，前往素有「72道瀑布之鄉」的勞特布魯嫩（Lauterbrunnen），欣賞峭壁懸泉的震撼美景 🌲⛰️","afternoon":"搭乘登山小火車前往翁根（Wengen），這座禁行汽車的純淨山城充滿寧靜，隨意挑選一間觀景咖啡館發呆 ☕🪟","evening":"回到因特拉肯，在隱密巷弄的溫馨小酒館享用慢烤牛排與手工啤酒 🥩🍻","coupleHighlight":"在瀑布旁的小橋上，聽著轟鳴的水聲，閉上眼睛讓另一半為自己披上喀什米爾圍巾 🧣💧"},{"day":5,"theme":"冰川列車・穿越阿爾卑斯的奢華鐵道戀曲 🚂","morning":"享用豐盛早餐後退房，登上世界聞名的「冰川列車（Glacier Express）」卓越艙（Excellence Class），展開頂級鐵道之旅 🥂🛤️","afternoon":"坐在全景玻璃車窗前，品嚐專屬主廚特製的五道式午餐與精選佐餐酒，細細品味窗外緩緩流動的雪山與峽谷風光 🍽️🍷","evening":"午後抵達終點策馬特（Zermatt），這座零碳排的環保山城空氣無比清新，入住阿爾卑斯木屋風格套房 🪵✨","coupleHighlight":"在冰川列車的酒吧車廂乾杯，窗外正好駛過宛如童話般的瑞士高山古橋與松林 🥂🌲"},{"day":6,"theme":"馬特洪峰日出・戈爾內格拉特觀景之旅 ☀️","morning":"清晨不需太早起，搭乘戈爾內格拉特（Gornergrat）齒軌登山火車，沿途等待著名的「金色馬特洪峰」晨光 🏔️💛","afternoon":"在標誌性的 Riffelsee 湖畔散步，欣賞無風時湖面上倒映的馬特洪峰完美倒影，宛如世外桃源 🌊📸","evening":"回到策馬特主街 Bahnhofstrasse，在百年糕點店挑選精緻的手工瑞士巧克力，漫步於石板路上 🍫🏮","coupleHighlight":"在 Riffelsee 湖邊靜靜依偎，看著雲霧在馬特洪峰的三角錐山尖緩緩流轉，享受只屬於彼此的安靜時刻 🤫🏔️"},{"day":7,"theme":"馬特洪峰冰川天堂・雲海之上的浪漫下午茶 🚡","morning":"享受慵懶的早晨，搭乘最高海拔的 3S 纜車前往馬特洪峰冰川天堂（Matterhorn Glacier Paradise） 🚠☁️","afternoon":"造訪歐洲最高的冰宮，觸摸晶瑩剔透的萬年冰雕，隨後在全景餐廳享用頂級的高山熱可可與蘋果派 🥧☕","evening":"漫步至策馬特古老的馬特村（Hinterdorf），欣賞傳統的瓦萊州黑色木屋建築群與掛滿鮮花的陽台 🏡🌸","coupleHighlight":"在海拔 3883 公尺的觀景台頂端，輕輕擁抱並在萬年雪山見證下交換一個高空深吻 💋❄️"},{"day":8,"theme":"五湖健行・阿爾卑斯高山湖泊的微風呢喃 🌲","morning":"輕鬆享用早午餐後，搭乘地下纜車與吊椅纜車前往 Sunnegga，展開平緩的精選短程高山健行 🥾🌿","afternoon":"沿著 Stellisee 與 Grindjisee 的平緩步道漫步，沿途野花遍野，偶爾能見到可愛的土撥鼠探頭打招呼 🌼🐾","evening":"在 Sunnegga 景觀露台餐廳，一邊享用現烤的瑞士香腸與薯餅（Rösti），一邊欣賞夕陽將馬特洪峰染成赤紅 🥔🌅","coupleHighlight":"在無人的高山湖畔草地上躺下來，把頭枕在另一半的大腿上，一起數著天空中漸漸冒出的繁星 ✨🌌"},{"day":9,"theme":"策馬特慢活購物・燭光告別晚宴 🕯️","morning":"沒有鬧鐘的早晨，在陽台上享用飯店準備的歐陸早餐，隨後漫步於策馬特精品小店挑選瑞士手錶與紀念品 🛍️⌚","afternoon":"造訪阿爾卑斯登山者墓地，感受百年攀登歷史的浪漫與傳奇，午後坐在街頭露天咖啡座喝拿鐵看行人 ☕📖","evening":"在策馬特米其林推薦或頂級木屋餐廳（如 The Omnia）享用浪漫燭光晚宴，為這趟旅程乾杯慶祝 🍷✨","coupleHighlight":"在滿天星斗的夜空下，牽著手在策馬特無車喧囂的街道上散步，聽著遠處教堂的晚禱鐘聲回盪 🌙🔔"},{"day":10,"theme":"甜蜜賦歸・帶著阿爾卑斯的記憶返回台灣 ✈️🇹🇼","morning":"享用最後一頓豐盛的瑞士早晨時光，帶著滿滿的行李與相機裡的美麗回憶，辦理退房手續 🥐🧳","afternoon":"搭乘 SBB 景觀火車經由菲斯普返回蘇黎世機場，沿途再次回味這十天來的雪山與湖泊風光 🚆👋","evening":"搭乘豪華客機起飛返回台灣，在機艙內沉沉睡去，夢見那座永遠閃耀著金光的馬特洪峰 🌙💤","coupleHighlight":"在登機前互相交換一本專屬於兩人的「瑞士旅行手札」，寫下對彼此未來更多次旅行的溫柔約定 📔🖊️"}],"mustTryFoods":["傳統瑞士起司鍋 (Authentic Swiss Cheese Fondue)","瓦萊州香煎馬鈴薯餅佐培根與蛋 (Valais-style Rösti)","冰川列車卓越艙精選主廚套餐 (Glacier Express Excellence Class Menu)","策馬特手工頂級瑞士巧克力 (Zermatt Artisanal Swiss Chocolate)"],"tips":"建議台灣旅客事先購買「瑞士旅遊通行證（Swiss Travel Pass 8天或15天連續券）」，不僅能無限次搭乘火車、遊船與巴士，還能享有少女峰與冰川列車的景觀車廂訂位折扣。夏季前往請務必攜帶高係數防曬乳、太陽眼鏡與輕便防風保暖外套（高山溫差大）；冬季則需準備防滑雪靴與觸控式保暖手套。強烈建議提早 3-4 個月預訂冰川列車的卓越艙（Excellence Class），以確保能坐在絕佳的雙人靠窗景觀座位。","generatedAt":1793467917376,"model":"gemini-3.5-flash-lite"}},{"id":"trip_perth","name":"西澳伯斯純淨海灘與短尾矮袋鼠島","locationName":"Perth, Australia","lat":-31.9505,"lng":115.8605,"minDays":6,"maxDays":8,"budget":"$$","costEstimate":"~NT$55,000 - 85,000 /人","seasons":["spring","autumn","summer"],"visited":false,"tags":["#短尾矮袋鼠","#科特索海灘","#天鵝河谷酒莊","#印度洋日落","#羅特尼斯島"],"description":"在羅特尼斯島尋找世界上最快樂的短尾矮袋鼠Quokka合照，漫步科特索海灘欣賞印度洋壯麗落日，造訪天鵝河谷品味頂級白葡萄酒。","itinerary":{"summary":"為Seb與Lynn量身打造的西澳慢活之旅，漫步於天鵝河畔的微風中、在粉紅海灘與微笑袋鼠旁私語，享受南半球最純淨的浪漫時光。","targetDays":7,"pace":"relaxed","days":[{"day":1,"theme":"抵達天鵝河畔・漫步伯斯市中心 🦢","morning":"搭乘班機抵達伯斯，輕鬆入住伊莉莎白碼頭（Elizabeth Quay）旁的奢華飯店，卸下行李稍作休息。","afternoon":"午後漫步於國王公園（Kings Park）的植物園，站在標誌性的玻璃天空步道俯瞰伯斯市景與天鵝河。","evening":"於碼頭邊的精緻餐廳享用西澳頂級黑安格斯牛排，佐以瑪格麗特河產區的微甜白酒。","coupleHighlight":"牽手坐在伊莉莎白碼頭的木棧道上，看夕陽將天鵝河染成金黃，分享一份剛出爐的肉桂吉拿棒 🥐"},{"day":2,"theme":"百年鐘樓與天鵝河漫遊 ⛵","morning":"睡到自然醒，前往伯斯人氣咖啡廳「Telegram Coffee」享用手沖咖啡與手工酸種麵包早餐。","afternoon":"悠閒造訪伯斯鑄幣局（Perth Mint），欣賞純金塊倒鑄的震撼，隨後在市中心海伊街（Hay Street）挑選精緻小物件。","evening":"搭乘天鵝河日落遊船，在徐徐晚風與柔和爵士樂聲中，欣賞水面上倒映的城市燈火。","coupleHighlight":"在遊船的露天甲板上，依偎著彼此互喝一杯溫熱的熱可可，任由微風吹亂髮絲 ☕"},{"day":3,"theme":"陽光與海風・寇蒂斯島渡假日常 🏝️","morning":"搭乘短程渡輪前往充滿地中海風情的羅特尼斯島（Rottnest Island），租借雙人腳踏車展開島嶼漫遊。","afternoon":"騎行至鮭魚灣（Salmon Bay）湛藍清澈的海灘，赤腳踩在細白沙灘上，尋找世界上最快樂的短尾矮袋鼠（Quokka）合影。","evening":"入住島上的奢華生態帳篷度假村，在無光害的星空下享用炭烤海鮮拼盤。","coupleHighlight":"蹲在灌木叢旁，輕聲逗弄一隻對著鏡頭微笑的短尾矮袋鼠，捕捉兩人與牠最萌的合影 📸"},{"day":4,"theme":"海島晨光與重返港都費利曼圖 ⚓","morning":"在島上的露台享用悠閒早餐，把握最後的晨光漫步於靜謐的鹽湖步道。","afternoon":"搭乘渡輪返回本島，轉往擁有維多利亞風情的古老港口城市費利曼圖（Fremantle），漫步於藝術家聚集的街道。","evening":"造訪歷史悠久的費利曼圖市集（Fremantle Markets），品嘗地道的炸魚薯條與手工精釀啤酒。","coupleHighlight":"在百年石造建築的街角長椅上，分食一份當地著名的義式冰淇淋，看街頭藝人的吉他彈唱 🍦"},{"day":5,"theme":"天鵝谷酒莊・微醺葡萄藤下 🍇","morning":"睡到飽後租車前往西澳最古老的葡萄酒產區—天鵝谷（Swan Valley），造訪擁有百年歷史的家族酒莊。","afternoon":"在莊園綠草地享用精緻的起司拼盤與頂級Shiraz紅酒品飲體驗，沉浸在南半球的慵懶鄉村步調。","evening":"入住酒莊附設的精品渡假小屋，窗外即是一望無際的葡萄園。","coupleHighlight":"在落日餘暉的葡萄藤架下輕輕擁抱，啜飲一口帶有莓果香氣的甜紅酒 🍷"},{"day":6,"theme":"印度洋絕美海岸・城市祕境漫遊 🌊","morning":"驅車前往伯斯北部的斯卡伯勒海灘（Scarborough Beach），在臨海咖啡廳「Livida Store」享用早午餐，欣賞印度洋壯闊海景。","afternoon":"返回市中心探索北橋（Northbridge）區的文青書店與街頭塗鴉藝術，感受伯斯的當代文化氣息。","evening":"在隱密的高空酒吧（Rooftop Bar）挑選靠窗座位，點一杯特調雞尾酒俯瞰閃爍的伯斯夜景。","coupleHighlight":"在海灘旁的天然潮汐泳池邊散步，任由微涼的海浪輕輕拍打腳踝，輕聲訴說這趟旅程的感動 🌊"},{"day":7,"theme":"慵懶道別・帶著南半球陽光賦歸 ✈️","morning":"在飯店享用豐盛的澳洲式早餐，最後漫步於伯斯市區的倫敦閣（London Court），挑選幾張明信片。","afternoon":"帶著滿滿的回憶前往伯斯機場，辦理退稅與登機手續，搭機返回台灣。","evening":"在舒適的機艙內相依偎，翻看手機裡這幾天拍下的海岸與短尾矮袋鼠照片。","coupleHighlight":"在機場免稅店挑選一瓶西澳特有的尤加利蜂蜜，作為兩人這趟純淨旅程最甜美的紀念 🍯"}],"mustTryFoods":["西澳黑安格斯牛排 (WA Black Angus Steak)","費利曼圖炸魚薯條 (Fremantle Fish and Chips)","羅特尼斯島短尾矮袋鼠造型餅乾 (Quokka Bakery Treats)","瑪格麗特河白蘇維濃白酒 (Margaret River Sauvignon Blanc)"],"tips":"1. 台灣直飛伯斯或經新加坡轉機極為方便，伯斯與台灣無時差，完全沒有調時差的困擾。\n2. 前往羅特尼斯島的渡輪與住宿務必提前三個月預訂，尤其是旺季一票難求。\n3. 西澳陽光強烈且紫外線高，防曬乳、太陽眼鏡與遮陽帽為每日必備隨身物品。","generatedAt":1793467938102,"model":"gemini-3.5-flash-lite"}},{"id":"trip_sydney","name":"雪梨海港大橋漫步與邦代海岸巡禮","locationName":"Sydney, Australia","lat":-33.8688,"lng":151.2093,"minDays":6,"maxDays":8,"budget":"$$","costEstimate":"~NT$58,000 - 88,000 /人","seasons":["spring","autumn","summer"],"visited":false,"tags":["#雪梨歌劇院","#海港大橋","#邦代海岸步道","#藍山國家公園","#海鮮市場"],"description":"乘渡輪掠過宏偉雪梨歌劇院與海港大橋，沿著邦代到庫吉海岸峭壁步道慢跑，日落時分在達令港海景露天酒吧微醺。","itinerary":{"summary":"為 Seb 與 Lynn 量身打造的雪梨慢活浪漫之旅，從環形碼頭的蔚藍海港到邦代海灘的金色日落，以慵懶的步伐與頂級咖啡香，交織出最溫柔的南半球雙人記憶。","targetDays":7,"pace":"relaxed","days":[{"day":1,"theme":"南半球初見・雪梨灣微風與歌劇院漫步 ⚓","morning":"搭乘長途航班抵達雪梨，入住環形碼頭（Circular Quay）旁的海景飯店，慵懶地換上輕便亞麻服裝，適應南半球的陽光與清爽空氣 🧳","afternoon":"在雪梨歌劇院（Sydney Opera House）外圍的 Opera Bar 找一張緊鄰海港的白色遮陽傘下落座，點一杯 Flat White 與新鮮生蠔，看白色風帆倒映在湛藍水面 🥂","evening":"漫步走過岩石區（The Rocks）的百年鵝卵石街區，在石造老屋改建的精緻餐酒館享用澳洲在地牛排與南澳紅酒 🥩","coupleHighlight":"牽手坐在歌劇院階梯上，等夕陽將天際染成粉紫色，聽著遠處傳來的街頭薩克斯風演奏，輕聲交換第一句晚安 🎶"},{"day":2,"theme":"百年鐵骨與浪漫夕陽・雪梨海港大橋漫步 🌉","morning":"睡到自然醒，前往雪梨植物園（Royal Botanic Garden）散步，走到「麥考利夫人的椅子」（Mrs Macquaries Chair）捕捉歌劇院與大橋同框的經典全景 🌳","afternoon":"午後展開重頭戲，沿著雪梨海港大橋（Sydney Harbour Bridge）的行人步道輕鬆漫步，俯瞰下方郵輪緩緩駛過與海灣的宏偉壯麗 👟","evening":"步行至大橋另一端的米佛爾（Milsons Point），在水岸餐廳 Luna Park Dining 享用晚餐，隔海遙望點燈後的雪梨市中心摩天大樓群 ✨","coupleHighlight":"在大橋的高處行人步道上，背對壯闊海灣，由 Seb 為 Lynn 拍下一張笑靨如花、髮絲隨海風飛揚的拍立得照片 📸"},{"day":3,"theme":"文青老街與海上渡輪・漫遊帕丁森與曼利 ⛴️","morning":"前往充滿維多利亞式建築的帕丁森（Paddington），逛逛週末市集，在獨立小店挑選香氛，並在巷弄內備受推崇的 Bills 享用著名的綿密瑞可達起司鬆餅 🥞","afternoon":"返回環形碼頭，搭乘經典的綠黃色公共渡輪前往曼利海灘（Manly Beach），在30分鐘的海上航程中享受太平洋的徐徐海風 🌊","evening":"赤腳踩在曼利海灘細軟的沙灘上，看衝浪客逐浪，隨後在海濱大道上的義大利小館共享一盤爐烤虎蝦海鮮手工寬麵 🦐","coupleHighlight":"回程的渡輪甲板上，依偎著彼此看著雪梨市中心夜景如星河般在眼前漸漸放大，享受只屬於兩人的靜謐時刻 🌃"},{"day":4,"theme":"海崖懸崖與蔚藍海岸・邦代海岸巡禮 🏖️","morning":"展開著名的邦代到庫吉海岸步道（Bondi to Coogee Coastal Walk）前半段，沿著金色懸崖與天然岩石泳池緩步前行，欣賞南太平洋的壯麗浪花 🌊","afternoon":"抵達南半球最具代表性的邦代海灘（Bondi Beach），在網紅地標 Icebergs Pool 旁的懸崖餐廳享用精緻午餐，看海浪拍打進泳池的震撼景致 🥗","evening":"在邦代海灘的時髦小酒館 Bondi Icebergs Club 露台，點一杯 Aperol Spritz 雞尾酒，欣賞夕陽緩緩沉入海岸線後方的住宅群 🍹","coupleHighlight":"在海岸步道的隱蔽觀景台停下腳步，兩人並肩坐在溫暖的砂岩上，靜靜聽著海濤聲，分享一顆剛買的澳洲手工冰淇淋 🍨"},{"day":5,"theme":"港灣隱密綠洲・Watsons Bay 浪漫尋秘 ⛵","morning":"悠閒地在達令赫斯特（Darlinghurst）的巷弄咖啡廳享用早午餐與澳式酪梨吐司，感受當地人的慢步調日常 🥑","afternoon":"搭乘渡輪前往華生灣（Watsons Bay），步行穿過寧靜的高級住宅區，登上波光粼粼的「世界盡頭」絕壁燈塔（Hornby Lighthouse），遠望太平洋無際水平線 🗼","evening":"在華生灣碼頭旁的 legendary Doyles on the Beach 享用經典的戶外炸魚薯條，看海鷗與夕陽在海面上交織成金色的畫布 🐟","coupleHighlight":"在燈塔旁的白色圍欄邊，迎著強勁卻清新的海風，十指緊扣承諾未來要一起去更多美麗的海角天涯 💌"},{"day":6,"theme":"藝術靈光與達令港煙火・雪梨當代饗宴 🎨","morning":"造訪位於港灣旁的當代藝術美術館（MCA），沈浸於南半球前衛的藝術創作中，並在頂樓咖啡館俯瞰繁忙的環形碼頭動態 🖼️","afternoon":"午後漫步前往達令港（Darling Harbour），在中國友誼花園旁的水岸長廊散步，累了就隨性找家設計感十足的茶館歇腳 🍵","evening":"在達令港水岸高級餐廳 Quay 享用當代頂級品嚐菜單，精緻的擺盤與窗外的港灣夜景互相輝映 ✨","coupleHighlight":"週末夜晚達令港的絢麗煙火在夜空中綻放時，Seb 從身後輕輕擁住 Lynn，在燦爛的光影下許下甜蜜的心願 🎆"},{"day":7,"theme":"最後的澳式咖啡香・南半球珍重再見 ☕","morning":"把握最後時光，造訪薩里山（Surry Hills）巷弄內最具在地靈魂的 Reuben Hills 咖啡館，品嚐冠軍手沖咖啡與極致班尼迪克蛋 🍳","afternoon":"在雪梨中央商業區（CBD）的 Queen Victoria Building（QVB）百年古典商場內選購精緻的澳洲伴手禮，如本地茶葉與天然護膚品 🛍️","evening":"帶著滿滿的浪漫回憶與曬得健康的小麥膚色，搭乘專車前往雪梨機場，登機返回台灣 ✈️","coupleHighlight":"在候機室準備登機前，兩人翻看著這七天累積的拍立得合照，相視而笑，約定好下一次的南半球假期 💖"}],"mustTryFoods":["澳式經典 Flat White 與特色早午餐 (Aussie Brunch & Flat White)","雪梨新鮮岩蠔與海鮮拼盤 (Sydney Rock Oysters & Seafood)","邦代海灘冰淇淋與手工甜點 (Bondi Gelato & Pastries)","頂級澳洲黑安格斯牛排與南澳紅酒 (Australian Wagyu/Angus Steak & Shiraz)"],"tips":"1. 交通免買實體卡：直接使用台灣具備感應功能的信用卡或手機 Apple Pay（Visa/Mastercard），即可輕鬆嗶卡搭乘雪梨所有地鐵、公車與渡輪。2. 防曬與保暖：澳洲紫外線極強，防曬乳、太陽眼鏡與遮陽帽為每日必備；春秋季節早晚溫差大，建議採洋蔥式穿搭。3. 預約建議：熱門海景餐廳（如 Icebergs Dining Room 或 Opera Bar 戶外座位）務必於出發前一個月上網完成預約。","generatedAt":1793468017335,"model":"gemini-3.5-flash-lite"}},{"id":"trip_paris","name":"巴黎塞納河畔藝術與左岸浪漫漫遊","locationName":"Paris, France","lat":48.8566,"lng":2.3522,"minDays":6,"maxDays":9,"budget":"$$","costEstimate":"~NT$78,000 - 125,000 /人","seasons":["spring","autumn"],"visited":false,"tags":["#艾菲爾鐵塔","#羅浮宮","#塞納河遊船","#左岸咖啡","#蒙馬特聖心堂"],"description":"在花神咖啡館享用法式可頌與歐蕾咖啡，黃昏搭乘塞納河遊船仰望艾菲爾鐵塔金色燈火，漫步蒙馬特石階俯瞰巴黎全景。","itinerary":{"summary":"為 Seb 與 Lynn 量身打造的巴黎漫遊，以塞納河的水波與左岸咖啡館的呢喃交織，每天僅留一至兩個深刻足跡，讓浪漫在慢時光裡自然流淌。","targetDays":8,"pace":"relaxed","days":[{"day":1,"theme":"左岸初相遇・塞納河畔第一道夕陽 ☕","morning":"抵達巴黎戴高樂機場，專車直達聖日耳曼德佩區精品酒店入住，在柔軟大床短暫休憩，調時差。","afternoon":"午後慵懶散步至傳奇的「花神咖啡館 Café de Flore」，挑選戶外緊鄰街景的雙人座，點一杯經典熱巧克力與法式可頌。","evening":"漫步至鄰近的藝術橋 (Pont des Arts)，在微涼晚風中眺望西提島與點燈的羅浮宮，感受巴黎初夜。","coupleHighlight":"在藝術橋的木棧道上並肩看著街頭藝人的吉他彈奏，輕輕牽手交換抵達巴黎的第一個吻 💋"},{"day":2,"theme":"文人足跡・盧森堡公園的綠蔭呢喃 🌳","morning":"睡到自然醒，前往當地傳統市集挑選新鮮無花果與手工起司，隨性開啟一場草地早午餐。","afternoon":"午後散步漫入「盧森堡公園 (Jardin du Luxembourg)」，租兩張經典綠色鐵椅，坐在美第奇噴泉旁讀詩、看白鴿。","evening":"前往左岸隱密的小酒館享用道地油封鴨腿佐波爾多紅酒，燭光下輕聲細語。","coupleHighlight":"在公園綠椅上共讀一本法文詩集，陽光穿透栗樹葉灑在彼此肩頭，享受無所事事的奢侈 📖"},{"day":3,"theme":"印象派殿堂・奧塞美術館的光影流轉 🎨","morning":"享用完精品咖啡與現烤布里歐許後，優雅步行至「奧塞美術館 (Musée d'Orsay)」，欣賞梵谷與莫內真跡。","afternoon":"登上美術館頂樓巨型時鐘後方，隔著復古鐘面剪影遠眺塞納河畔與蒙馬特聖心堂。","evening":"在美術館內的百年 Belle Époque 餐廳享用精緻法式晚餐，水晶吊燈下品嚐現切牛排。","coupleHighlight":"在巨型鐘面背後合影，將彼此的身影定格在百年時光剪影中 🕰️"},{"day":4,"theme":"拉丁區巷弄・莎士比亞書店的泛黃書香 📚","morning":"慵懶的早晨，前往塞納河畔尋找綠皮舊書攤 (Bouquinistes)，翻找一本百年舊明信片。","afternoon":"午後鑽進「莎士比亞書店 (Shakespeare and Company)」，在二樓窗檯伴隨老鋼琴的音符閱讀。","evening":"造訪隱身於巷弄內的百年經典小餐館，品嚐正統法式洋蔥湯，濃郁起司融化舌尖。","coupleHighlight":"在莎士比亞書店蓋上專屬紀念章，並寫下一張只屬於彼此的浪漫情書悄悄寄出 💌"},{"day":5,"theme":"皇室私藏・皇家宮殿花園的寧靜漫步 👑","morning":"睡個深眠的早晨，搭乘地鐵前往「皇家宮殿花園 (Palais-Royal)」，避開人潮，享受寧靜。","afternoon":"在花園內知名的黑白柱藝術裝置旁嬉戲拍照，隨後造訪百年廊道中的隱密香水沙龍，挑選兩人的專屬香氣。","evening":"沿著塞納河漫步至新橋 (Pont Neuf)，在河畔米其林推薦餐廳享用精緻晚宴。","coupleHighlight":"在香水沙龍裡為對方挑選一款氣味，讓未來的旅程都有了彼此專屬的巴黎氣息 🌸"},{"day":6,"theme":"瑪黑區時光・小特里亞農宮的浪漫微風 🏛️","morning":"搭乘 RER 前往凡爾賽宮，直奔較少人喧囂的「小特里亞農宮與愛神殿」，感受法式皇家園林的私密。","afternoon":"午後重返巴黎市區的「瑪黑區 (Le Marais)」，穿梭在中世紀古老街道，探索獨立設計師選品店。","evening":"在瑪黑區排隊品嚐當地傳奇的貝瑟餅乾與手工冰淇淋，坐在街角石階上分食。","coupleHighlight":"在愛神殿前的大片草地上踩著落葉散步，享受屬於兩人的私密法式莊園時光 🍃"},{"day":7,"theme":"蒙馬特絕景・雙心丘的夕陽告白 🍷","morning":"慢節奏的早餐後，前往藝術家聚集的「蒙馬特 (Montmartre)」，搭乘復古纜車緩緩上山。","afternoon":"牽手尋找小丘廣場的街頭畫家，讓畫家為兩人留下俏皮而溫馨的雙人肖像畫。","evening":"夕陽西下時分，坐在聖心堂前的白色台階上，俯瞰整座燈火逐漸亮起的巴黎全景。","coupleHighlight":"在聖心堂台階的金色夕陽下，聆聽街頭藝人的浪漫大提琴演奏，許下下一次同遊的約定 🎻"},{"day":8,"theme":"晨光告別・塞納河私人遊船的最終呢喃 ⛵","morning":"在左岸最後一間轉角咖啡館享用咖啡與可頌，打包這七天累積的香水與滿滿回憶。","afternoon":"午後包下一艘經典復古木質塞納河遊船，手拿香檳，在水面上最後一次凝望巴黎地標。","evening":"專車接送前往機場，帶著滿滿的浪漫與不捨，搭機返回台灣。","coupleHighlight":"在遊船駛過亞歷山大三世橋的瞬間，舉起香檳向巴黎乾杯，為這趟慢活之旅畫下完美句點 🥂"}],"mustTryFoods":["花神咖啡館熱巧克力與奶油可頌 (Chocolat Chaud & Croissant)","左岸傳統油封鴨腿佐波爾多紅酒 (Confit de Canard)","法式經典焗烤洋蔥湯 (Soupe à l'Oignon)","瑪黑區手工法式冰淇淋 (Artisanal Gelato)"],"tips":"1. 交通建議：下載 Île-de-France Mobilités App 並購買 Navigo Easy 卡儲值，搭乘地鐵與公車最為便捷。2. 預約提醒：奧塞美術館、莎士比亞書店周邊以及熱門咖啡館強烈建議提前兩個月官網預約，避免排隊打壞漫遊興致。3. 穿搭建議：巴黎石板路極多，Seb 與 Lynn 務必攜帶好走的皮革休閒鞋或樂福鞋，並以多層次洋蔥穿搭應對早晚溫差。","generatedAt":1793468016590,"model":"gemini-3.5-flash-lite"}},{"id":"trip_hanoi","name":"越南河內古街慢活與下龍灣海上巡航","locationName":"Hanoi, Vietnam","lat":21.0285,"lng":105.8542,"minDays":4,"maxDays":6,"budget":"$","costEstimate":"~NT$15,000 - 24,000 /人","seasons":["autumn","winter","spring"],"visited":false,"tags":["#三十六古街","#下龍灣過夜郵輪","#越南蛋咖啡","#法式越菜","#還劍湖"],"description":"穿梭充滿法式殖民風情的三十六古街品嚐濃郁蛋咖啡與道地生牛肉河粉，搭乘豪華郵輪在世界自然遺產下龍灣奇岩石林間划獨木舟。","itinerary":{"summary":"為 Seb 與 Lynn 打造的慢活浪漫之旅，從河內三十六古街的法式拿鐵與蛋咖啡開始，到下龍灣雙人奢華遊船上的海上日落與星空晚餐，享受零趕行程的私密時光。","targetDays":5,"pace":"relaxed","days":[{"day":1,"theme":"抵達法式風情古都・漫步三十六古街 🏮","morning":"搭乘班機由台灣出發抵達河內，專車接送至市中心，輕鬆入住還劍湖畔精品飯店，調整心情。","afternoon":"午後慵懶起床，造訪隱身於古街老宅的 Dinh Café，品嚐經典濃郁的傳統越南蛋咖啡 (Cà phê trứng)。","evening":"牽手漫步還劍湖畔，欣賞點燈後的棲旭橋與紅色的龜塔倒影，在湖畔景觀餐廳享用精緻越法融合晚餐。","coupleHighlight":"在微涼的晚風中，並肩坐在還劍湖畔的石椅上，分食一份酥脆的越南法棍麵包 (Bánh mì)，看著緩慢流動的街頭光影 🥖"},{"day":2,"theme":"鐵道咖啡與湖畔文藝微光 ☕","morning":"睡到自然醒，在飯店享用緩慢早餐。隨後前往著名的河內火車街 (Hanoi Train Street)，挑選一間安全距離內的二樓陽台咖啡館。","afternoon":"午後探訪擁有百年歷史的聖約瑟夫大教堂 (St. Joseph's Cathedral)，在周邊法式小店尋找精緻手作紀念品。","evening":"前往隱密浪漫的 neo-Indochine 風格餐酒館，品嚐香茅蒸蛤蜊與精釀啤酒，享受私密對話。","coupleHighlight":"火車呼嘯而過的那一刻，兩人緊緊相依在陽台的藤椅上，笑著捕捉這張充滿衝突美感的合照 🚂"},{"day":3,"theme":"駛入世界遺產・下龍灣海上漫遊 ⛵","morning":"享用悠閒早餐後，搭乘豪華舒適的接駁專車前往下龍灣 (Ha Long Bay)，沿途欣賞遼闊的越南北部田園風光。","afternoon":"中午登上下龍灣五星級過夜遊船，辦理入住後享用海鮮自助午餐，遊船緩緩駛入千島百嶼的碧綠海域。","evening":"參加船上舉辦的夕陽派對，在甲板躺椅上欣賞落日將石灰岩山染成金黃，隨後享用浪漫燭光晚餐。","coupleHighlight":"夜幕低垂時，兩人依偎在船尾的私密陽台上，聽著海浪輕拍船身，抬頭數著海上無光害的滿天繁星 ✨"},{"day":4,"theme":"海上晨光與重返古街慢時光 🌊","morning":"清晨在甲板上參加雙人太極拳課程，迎著海風深呼吸，隨後搭乘小船探索神祕的鐘乳石洞。","afternoon":"依依不舍告別遊船，乘車返回河內古街。入住靜巷內的精品設計旅店，午後在 Cong Caphe 喝椰子冰咖啡。","evening":"造訪東河門附近的在地小吃名店，品嚐享譽國際的越南烤肉米線 (Bún chả)。","coupleHighlight":"在充滿復古軍綠色調的文青咖啡館角落，妳一口我一口地品嚐著冰涼清甜的椰子咖啡沙冰 🥥"},{"day":5,"theme":"最後的法式甜點・帶著滿滿溫柔賦歸 🍰","morning":"睡到飽後，前往河內歌劇院旁的法式咖啡館 Maison Marou，享用頂級手工越南單一產地熱巧克力與法式千層派。","afternoon":"在同春市場周邊挑選幾包高品質的越南羅布斯塔咖啡豆與手工伴手禮，為旅行留下氣味記憶。","evening":"專車前往河內內排國際機場，辦理登機手續，搭機返回台灣，結束完美的浪漫假期。","coupleHighlight":"在機場候機時，兩人頭靠著頭翻閱這幾天拍下的拍立得照片，相約下一次的私密旅行 ✈️"}],"mustTryFoods":["越式蛋咖啡 (Cà phê trứng)","越南烤肉米線 (Bún chả)","下龍灣新鮮現撈海鮮料理","法式巧克力甜點 (Maison Marou)"],"tips":"1. 台灣旅客前往越南需事先辦理電子簽證 (E-visa)，請於出發前兩週完成申請。\n2. 河內古街過馬路需保持穩定步伐緩慢前行，當地機車會自動閃避，切勿突然奔跑或停下。\n3. 下龍灣過夜遊船建議提前 2-3 個月預訂，以確保能挑選到景觀最佳的雙人面海陽台房型。","generatedAt":1793468011245,"model":"gemini-3.5-flash-lite"}},{"id":"trip_england","name":"英國倫敦泰晤士河與科茲窩童話鄉村","locationName":"London & Cotswolds, England","lat":51.5074,"lng":-0.1278,"minDays":7,"maxDays":10,"budget":"$$","costEstimate":"~NT$82,000 - 135,000 /人","seasons":["summer","spring","autumn"],"visited":false,"tags":["#倫敦眼","#大笨鐘","#科茲窩蜜糖石屋","#大英博物館","#英式下午茶"],"description":"在倫敦眼座艙俯瞰泰晤士河晨光，體驗傳統三層英式下午茶，自駕深入科茲窩漫步於蜂蜜色古老石屋與玫瑰花園之間。","itinerary":{"summary":"專為Seb與Lynn打造的慢活英倫之旅，從泰晤士河畔的微風與當代藝術交織，到科茲窩蜜色石屋的漫霧晨光，以不疾不徐的步伐，細品英式浪漫。","targetDays":9,"pace":"relaxed","days":[{"day":1,"theme":"抵達倫敦・泰晤士河畔的黃昏微風 🌆","morning":"搭乘長途航班抵達倫敦希斯洛機場，專車入住市中心飯店（如 Covent Garden 區域），在房內細緻開箱、緩解時差。","afternoon":"午後慵懶散步至泰晤士河畔，坐在千禧橋（Millennium Bridge）旁河階，看著泰特現代美術館（Tate Modern）外側的街頭藝人表演。","evening":"在 South Bank 享用浪漫的迎賓晚餐，品嚐道地英式碳烤牛排與一杯微醺的 Pimms 酒。","coupleHighlight":"傍晚並肩坐在南岸長椅上，看著國會大廈與倫敦眼漸漸亮起燈火，手握著一杯熱可可驅散初抵的微涼夜風 ☕"},{"day":2,"theme":"藝文與私房市集・諾丁丘的繽紛漫步 🎨","morning":"睡到自然醒，前往波特貝羅路市集（Portobello Road Market）穿梭於粉嫩色調的維多利亞式建築間，挑選復古明信片。","afternoon":"午後散步至肯辛頓花園（Kensington Gardens），在皇家圓形劇場旁的 Serpentine 湖畔咖啡館享用精緻下午茶。","evening":"漫步至鄰近的 Notting Hill 小酒館，享用輕鬆的當代英國酒館料理。","coupleHighlight":"在諾丁丘一棟湛藍色老屋轉角，互相幫對方拍下一張電影感十足的底片風格合照 📸"},{"day":3,"theme":"泰晤士河經典・西敏與倫敦眼摩天輪 🎡","morning":"悠閒享用飯店早餐，上午漫步通過西敏橋，仰望大笨鐘與西敏寺的宏偉哥德式建築線條。","afternoon":"午後預約私人包廂式的倫敦眼（London Eye）慢速高空迴旋，俯瞰整個大倫敦的壯麗天際線。","evening":"搭乘 Uber Boat 觀光河輪順流而下，欣賞黃昏金色餘暉灑落在塔橋（Tower Bridge）上的絕美景致。","coupleHighlight":"在緩緩移動的河輪甲板上，迎著晚風輕輕依偎，倒映著倫敦塔橋的閃爍燈光乾杯 🥂"},{"day":4,"theme":"告別都會・駛入科茲窩童話鄉村 🏡","morning":"上午於 Paddington 車站取車或搭乘火車前往莫頓因馬什（Moreton-in-Marsh），沿途窗外綠意漸濃，抵達後入住科茲窩傳統蜜色石屋旅館。","afternoon":"午後造訪斯托昂溫德拉什（Stow-on-the-Wold），探訪被古老紫杉樹包圍、宛如精靈小屋的聖愛德華教堂木門。","evening":"在鄉村爐火旁的百年石造小酒館（Inn）享用慢燉羊膝與溫熱蘋果派。","coupleHighlight":"在被夕陽染成金黃色的石牆巷弄間散步，四周只有遠處的羊群叫聲和彼此的腳步聲 🐑"},{"day":5,"theme":"拜伯里與水上伯頓・詩意水鄉漫遊 🦢","morning":"睡個深沉的鄉村懶覺，上午前往被威廉·莫里斯譽為「全英格蘭最美村莊」的拜伯里（Bibury），欣賞亞靈頓排屋（Arlington Row）。","afternoon":"午後前往「科茲窩威尼斯」水上伯頓（Bourton-on-the-Water），在淺淺清澈的溫德拉什河畔野餐或找家河畔咖啡廳發呆。","evening":"回到安靜的鄉村旅館，泡個熱水澡，享受無光害的滿天星空。","coupleHighlight":"坐在水上伯頓橫跨小河的低矮石拱橋上，兩個人分食一份熱騰騰的英式司康佐濃縮鮮奶油 🫖"},{"day":6,"theme":"丘吉爾莊園・巴洛克式皇家花園漫步 👑","morning":"上午前往世界文化遺產布萊尼姆宮（Blenheim Palace，邱吉爾莊園），漫步於氣勢磅礡的宮殿長廊。","afternoon":"午後在莊園的宏大水上花園與玫瑰園漫步，欣賞修剪整齊的綠籬迷宮與倒影池。","evening":"驅車前往鄰近古鎮伍德getStock或返回倫敦，在市區安靜的義大利小館享用手工義麵。","coupleHighlight":"在邱吉爾莊園的巨大林蔭大道下踩著落葉散步，假裝自己是英式莊園的主人與夫人 🍂"},{"day":7,"theme":"柯芬園的文藝與百年茶香・倫敦重返 🍵","morning":"上午返回倫敦市中心，漫步至柯芬園（Covent Garden）欣賞街頭藝術表演，逛逛手工藝市集。","afternoon":"午後前往 Fortnum & Mason 享用傳承百年的經典三層英式下午茶，細細品嚐銀器與骨瓷杯交織的優雅時光。","evening":"欣賞一場西區（West End）經典音樂劇（如《歌劇魅影》或《悲慘世界》），沈浸於震撼人心的旋律中。","coupleHighlight":"在百年茶館裡互挑一罐帶有英倫香氣的特調茶葉，作為這趟旅程的氣味記憶 🌿"},{"day":8,"theme":"大英博物館的私密對話・泰晤士河畔告別晚宴 🏛️","morning":"上午避開人潮，以最悠閒的步調造訪大英博物館（British Museum），只挑選古埃及與希臘羅馬館展品細細觀賞。","afternoon":"午後在蘇荷區（Soho）巷弄中尋找獨立書店與黑膠唱片行，隨意找家質感咖啡館喝杯 Flat White。","evening":"在泰晤士河畔米其林推薦餐廳（如 OXO Tower Restaurant）享用頂級告別晚餐，落地窗外正對著聖保羅大教堂。","coupleHighlight":"在燭光晚餐的尾聲，相視交換這八天來各自最心動的私房瞬間，將溫柔鎖進倫敦的夜色中 🕯️"},{"day":9,"theme":"晨光書店與甜蜜返程・英倫再見 ✈️","morning":"最後一早漫步至 St. James's Park 看鵜鶘曬太陽，在百年老字號咖啡館享用悠閒早午餐。","afternoon":"整理行李，帶著滿滿的戰利品與溫暖回憶，搭乘專車前往機場辦理退稅與登機手續，搭機返回台灣。","evening":"在飛機上靠著彼此的肩膀，翻閱著這幾天拍下的照片，帶著微笑進入夢鄉。","coupleHighlight":"在機場入關前給彼此一個深情的擁抱，約定好下一次的私密旅行目的地 ✈️"}],"mustTryFoods":["傳統英式下午茶（三層塔、司康佐 Clotted Cream 與果醬）","經典碳烤威靈頓牛排或科茲窩慢燉羊膝","英式炸魚薯條（Fish and Chips）搭配手工塔塔醬","濃郁絲滑的 Flat White 澳白咖啡與肉桂捲"],"tips":"1. 交通建議：倫敦市區全面使用感應式信用卡或 Apple Pay 刷地鐵與公車，極為便利；若前往科茲窩，強烈建議租車自駕以享受鄉間隨停隨拍的自由浪漫。2. 預約提醒：西區音樂劇門票、Fortnum & Mason 下午茶及科茲窩熱門餐廳務必於出發前 2-3 個月完成預約。3. 穿搭準備：英國天氣多變，採洋蔥式穿搭並攜帶防風防潑水的外套與好走的樂福鞋或短靴最為實用。","generatedAt":1793468031998,"model":"gemini-3.5-flash-lite"}},{"id":"trip_newzealand","name":"紐西蘭皇后鎮冰川峽灣與瓦卡蒂普湖","locationName":"Queenstown, New Zealand","lat":-45.0312,"lng":168.6626,"minDays":9,"maxDays":14,"budget":"$$","costEstimate":"~NT$88,000 - 145,000 /人","seasons":["summer","autumn","spring"],"visited":false,"tags":["#米佛峽灣","#皇后鎮纜車","#瓦卡蒂普湖","#魔戒取景地","#極致星空"],"description":"沿著世界最美高山公路開往米佛峽灣瀑布群，在瓦卡蒂普湖畔悠閒漫遊，夜晚在蒂卡波湖暗空保護區抬頭仰望南十字星與璀璨銀河。","itinerary":{"summary":"為 Seb 與 Lynn 打造的 12 天紐西蘭南島慢活浪漫之旅，以皇后鎮為核心，在瓦卡蒂普湖的湖光山色與冰川峽灣間，享受沒有鬧鐘的晨光與私密微醺時光。","targetDays":12,"pace":"relaxed","days":[{"day":1,"theme":"抵達南島・瓦卡蒂普湖畔初見 🏔️","morning":"搭乘長途航班抵達皇后鎮機場，由專車接送至面湖的隱密奢華渡假村辦理入住，稍作梳洗。","afternoon":"在陽台上品嚐迎賓白蘇維濃白酒，慵懶觀賞受冰川雕琢的瓦卡蒂普湖面上波光粼粼。","evening":"散步前往市區的 Flame Bar & Grill，享用炭烤紐西蘭頂級肋眼牛排，佐當地產的黑皮諾紅酒。","coupleHighlight":"晚餐後在湖畔棧道牽手散步，聽著街頭藝人的吉他聲，在南半球的星空下輕輕依偎。"},{"day":2,"theme":"百年蒸氣船・穹蒼之下的華麗午茶 🚢","morning":"睡到自然醒，悠閒享用飯店早餐。午後緩步走到湖濱碼頭，登上 1912 年啟航的恩斯洛號蒸氣船 (TSS Earnslaw)。","afternoon":"乘船航行至瓦尔特峰高原牧场 (Walter Peak)，在歷史悠久的上校農舍享用精緻的爐烤下午茶點。","evening":"搭乘蒸氣船返航，夕陽將群山染成柔和的粉紫色，回到皇后鎮溫馨的私人小酒館吃手工義大利麵。","coupleHighlight":"在蒸氣船的木質甲板上，迎著微涼湖風，彼此依偎著捕捉山水交融的浪漫合影。"},{"day":3,"theme":"雲端之上・俯瞰南阿爾卑斯山 🚠","morning":"深夜不設鬧鐘，午後搭乘 Skyline 纜車緩緩升空，俯瞰被冰川環抱的皇后鎮全景。","afternoon":"在海拔高處的 Stratosfare 景觀餐廳享用慢步調的午茶，隔著落地窗眺望卓越山脈 (The Remarkables)。","evening":"坐在纜車山頂露台，細看夕陽漸漸沉入山谷，燈火逐一亮起如星光墜落人間。","coupleHighlight":"在山頂無人的觀景角落，輕輕擁抱著彼此，看著整座小鎮被暮色溫柔包裹。"},{"day":4,"theme":"世界盡頭的峽灣・米爾福德深度巡航 🌊","morning":"清晨搭乘小型觀光飛機出發，從高空俯瞰冰川切割出的壯麗峽灣地貌，直接飛抵米爾福德峽灣。","afternoon":"登上豪華雙體船巡航塔斯曼海的峽灣深處，感受峭壁千仞與萬年冰川瀑布直瀉而下的震撼。","evening":"乘飛機返回皇后鎮，在市區隱密的 Bodega 餐廳品嚐西班牙 tapas 與微醺調酒。","coupleHighlight":"當飛機穿梭在群山峽谷間時，緊緊握住彼此的手，體驗宛如世界盡頭私奔的浪漫。"},{"day":5,"theme":"魔戒小鎮・格林諾奇的鏡面秘境 🌲","morning":"睡到自然醒後租車出發，沿著被譽為全球最美公路之一的格林諾奇公路 (Glenorchy Road) 緩開。","afternoon":"抵達被群山環繞的格林諾奇碼頭與沼澤步道，漫步於平靜如鏡的湖濱，尋找精靈寶鑽的拍攝足跡。","evening":"返回皇后鎮，在市區知名海鮮餐廳 Flame 或 Fishbone 享用現釣的紐西蘭國王鮭 (King Salmon)。","coupleHighlight":"在無人的湖畔枯木旁，並肩坐在長椅上安靜喝著熱咖啡，享受只屬於兩人的寧靜時光。"},{"day":6,"theme":"果園花香・緩慢漫步箭鎮古老街區 🍂","morning":"早晨造訪擁有淘金歷史的箭鎮 (Arrowtown)，漫步於被秋葉或春花覆蓋的 19 世紀淘金小屋街道。","afternoon":"造訪當地的 The Remarkable Sweet Shop 手工糖果店，挑選復古的傳統軟糖，隨後在獨立咖啡館喝一杯 Flat White。","evening":"驅車前往吉布斯頓谷 (Gibbston Valley) 的葡萄園酒莊餐廳，享用慢燉羊膝搭配頂級冰酒。","coupleHighlight":"在百年古樹下共撐一把傘或並肩散步，隨性挑選一瓶當地葡萄酒作為兩人的紀念收藏。"},{"day":7,"theme":"冰川之眼・法蘭士約瑟夫溫泉私密時光 ❄️","morning":"沿著西海岸公路北上，前往法蘭士約瑟夫冰川 (Franz Josef Glacier) 地區，沿途欣賞雨林與冰河交織的奇景。","afternoon":"入住森林深處的隱蔽樹屋飯店，午後前往冰川溫泉 (Glacier Hot Pools) 享受被綠意包圍的私人露天溫泉池。","evening":"在溫泉區附近的 Monsoons 餐廳享用暖心的東南亞融合料理，為微涼的雨林夜晚增添暖意。","coupleHighlight":"在氤氳蒸氣的私密溫泉池中，仰望南半球澄淨的星空，享受冰火交融的極致放鬆。"},{"day":8,"theme":"萬年冰雪・冰川健行與冰洞探秘 🚁","morning":"搭乘直升機飛越法蘭士約瑟夫冰川的湛藍冰隙，降落在遊客罕至的高海拔冰原上。","afternoon":"在專業嚮導帶領下，穿上冰爪輕輕探索藍色冰洞與冰瀑，感受大自然的鬼斧神工。","evening":"結束驚豔的冰川之旅後回到鎮上，在 Alice May 藝廊餐廳品嚐手作漢堡與精釀啤酒。","coupleHighlight":"在直升機機艙內起飛的瞬間，興奮地對看並緊緊相握，共享一場冒險的浪漫。"},{"day":9,"theme":"返航皇后鎮・湖畔漫時光與伴手禮 🎁","morning":"睡到自然醒，享用悠閒早餐後，開車緩緩南返皇后鎮，沿途隨性在觀景台停靠欣賞湖景。","afternoon":"午後回到皇后鎮市區，在 Perky's Floating Bar 浮動酒吧的船甲板上，喝著熱紅酒看水鴨悠遊。","evening":"前往 Fergburger 買傳說中的鹿肉漢堡，外帶到瓦卡蒂普湖畔草地上野餐享用。","coupleHighlight":"肩並著肩坐在湖邊草皮上，一邊分食漢堡，一邊看著夕陽將天空染成一片浪漫的玫瑰金。"},{"day":10,"theme":"芳療私語・尊榮Spa與高空跳傘旁觀 💆","morning":"今天徹底放慢腳步，前往 Onsen Hot Pools 預約頂級私人溫泉亭，浸泡在面山河谷的檜木熱水池中。","afternoon":"享受兩小時的雙人芳療按摩，將旅途的疲憊全數釋放，隨後在皇后鎮花園漫步。","evening":"預約當地首屈一指的 Bardeaux 威士忌與紅酒酒吧，在壁爐旁輕輕碰杯。","coupleHighlight":"在私人溫泉亭內，望著窗外壯麗的峽谷景致，與對方分享一杯香檳，低語呢喃。"},{"day":11,"theme":"微醺公路・吉布斯頓谷酒莊奢華午宴 🍇","morning":"上午睡到自然醒，前往當地極具口碑的 Vknow 餐廳享用精緻早午餐。","afternoon":"造訪 Peregrine Wines 建築大師設計的現代酒莊，品嚐屢獲大獎的麗絲玲與黑皮諾紅酒。","evening":"返回皇后鎮市區，在 Rātā 餐廳享用紐西蘭名廚 Michelin 等級的當代紐式料理浪漫燭光晚餐。","coupleHighlight":"在米其林級的餐桌上品嚐甜點時，回憶這 11 天點滴，互相交換寫給彼此的一封手寫信。"},{"day":12,"theme":"依依不舍・帶回滿載星光的記憶 ✈️","morning":"最後一日不設鬧鐘，在飯店陽台享用最後一杯紐西蘭鮮奶與手工烘焙麵包，看湖水泛著晨霧。","afternoon":"在鎮上挑選純淨的麥蘆卡蜂蜜與羊毛製品當作伴手禮，最後在 Patagonia Chocolates 喝一杯濃郁熱可可。","evening":"專車接送至皇后鎮機場，帶著滿滿的浪漫回憶，搭機經轉機返回台灣。","coupleHighlight":"在登機前緊緊擁抱，約定好下一次還要一起探索世界的更多角落。"}],"mustTryFoods":["Fergburger 經典鹿肉或牛肉漢堡","紐西蘭頂級國王鮭 (King Salmon) 料理","Gibbston Valley 黑皮諾紅酒與冰酒","Patagonia Chocolates 手工冰淇淋與熱可可"],"tips":"1. 紐西蘭紫外線強烈且氣候多變，即使是春夏季節也請務必攜帶防曬用品與防風保暖外套。 2. 皇后鎮的 Onsen Hot Pools 與高空溫泉極為搶手，建議出發前 3-4 個月完成預約。 3. 台灣旅客前往紐西蘭需事先申請 NZeTA (電子旅行授權) 與繳納國際遊客保護及旅遊稅 (IVL)。","generatedAt":1793468044746,"model":"gemini-3.5-flash-lite"}},{"id":"trip_okinawa","name":"沖繩蔚藍跳島與古宇利海景自駕","locationName":"Okinawa, Japan","lat":26.2124,"lng":127.6809,"minDays":4,"maxDays":6,"budget":"$$","costEstimate":"~NT$28,000 - 45,000 /人","seasons":["summer","spring","autumn"],"visited":false,"tags":["#慶良間藍","#古宇利大橋","#海龜共游","#海景自駕","#石垣牛"],"description":"開著車沿著古宇利跨海大橋奔馳，在世界級慶良間藍海域與海龜浮潛，傍晚在美國村落日海灘享用石垣牛美食。","itinerary":{"summary":"為 Seb 與 Lynn 打造的沖繩蔚藍與老屋慢時光，以睡到自然醒的慵懶步調，穿梭於琉球古民家微風與漸層海藍之間，在海浪聲與夕陽中寫下屬於兩人的浪漫詩篇。波","targetDays":5,"pace":"relaxed","days":[{"day":1,"theme":"抵達沖繩・港川外人住宅老屋微風 🏡","morning":"搭乘早班機從台灣飛抵那霸機場，取車後前往浦添港川外人住宅區，在充滿美國復古風情的白色老屋群中漫步，挑選一間質感手作雜貨店。 🌿","afternoon":"慵懶地落腳於人氣咖啡館「oHacorte」，挑選一顆季節水果塔，與 Lynn 坐在綠意盎然的庭院木桌旁品嚐下午茶。 🥧","evening":"入住沖繩海濱度假飯店，換上輕便亞麻情侶裝，赤腳踩在美國村附近的海岸防波堤上，看夕陽將海面染成溫柔的粉橘色。 🌅","coupleHighlight":"在夕陽餘暉的海岸邊，兩人共飲一杯沖繩特產的冰涼 Orion 啤酒，任由海風輕拂髮梢。 🍻"},{"day":2,"theme":"蔚藍海潮・美國村與浪漫海景日落 🌊","morning":"享受沒有鬧鐘的早晨，在飯店享用豐盛的沖繩在地早餐後，悠閒驅車前往北谷町的美濱美國村，漫步於充滿異國風情的色彩街道。 🏘️","afternoon":"午後造訪臨海的「Transit Cafe」，坐在二樓露台的沙發座位，俯瞰波光粼粼的東中國海，並肩共享一份鬆軟的現烤鬆餅。 🥞","evening":"漫步至日落海灘（Sunset Beach），聽著海浪輕拍岸邊，牽手看著太陽緩緩沒入海平線深處。 🧡","coupleHighlight":"在日落海灘的木棧道上緊緊相依，拍下一張背光卻充滿愛意的剪影照片。 📸"},{"day":3,"theme":"古宇利蔚藍神話・海中道路浪漫漫遊 🌉","morning":"睡到自然醒後北上，駕車駛過筆直壯闊的古宇利大橋，彷彿行駛在蔚藍無垠的雙色海洋正中央。 🚗","afternoon":"造訪古宇利島上的「L LOTTA」海景咖啡廳，品嚐精緻的在地食材輕食，落地窗外就是絕美的的心型岩海岸景致。 ☕","evening":"入住本部町的奢華海景度假村，在私人陽台上聽著海潮聲，享用主廚特製的沖繩黑毛和牛晚餐。 🥩","coupleHighlight":"夜深時分，兩人躺在度假村陽台的躺椅上，無光害的星空下輕聲細語，尋找南十字星。 ✨"},{"day":4,"theme":"琉球文藝・讀谷村陶藝村落與海景茶屋 🏺","morning":"睡個飽覺後前往充滿藝術氣息的讀谷村「壺屋燒物鄉」，走入傳統紅瓦老屋改建的陶藝工作室，挑選一只手作情侶對杯。 🍶","afternoon":"午後前往隱密的海景茶屋「Garaguya」，坐在被大自然環抱的戶外座席，品嚐手沖黑糖咖啡與手工磅蛋糕。 🍰","evening":"返回那霸市區，入住國際通巷弄內的設計感精品酒店，卸下行李後輕鬆逛逛夜市。 🏮","coupleHighlight":"在老屋茶屋的樹蔭下，兩人互相幫對方挑選了一款帶有沖繩海洋藍釉彩陶杯。 🌿"},{"day":5,"theme":"國際通老街散策・帶著滿滿海島記憶返航 ✈️","morning":"在國際通巷弄的文青咖啡館「Cinnamon Cafe」享用精緻早午餐，細細回味這幾天的海風與陽光。 🍳","afternoon":"前往牧志公設市場周邊選購精緻伴手禮，最後在平和通商店街的復古喫茶店喝一杯冰涼的黑糖漂浮冰咖啡，享受最後的悠閒時光。 🧊","evening":"前往那霸機場，搭乘班機返回台灣，結束這場浪漫的琉球漫時光。 ✈️","coupleHighlight":"在機場入關前，沈穩地牽起 Lynn 的手，約定好下次還要一起來看沖繩的海。 🤝"}],"mustTryFoods":["沖繩阿古豬（Agu Pork）涮涮鍋","古宇利島蝦飯（Shrimp Wagon）","品嚐口感Q彈的沖繩極品海葡萄","道地黑糖蜜剉冰與手作紅芋塔"],"tips":"1. 建議於那霸機場提早預約租車（含MapCode導航功能），自駕是探索沖繩海岸最浪漫且彈性的方式。 2. 7-8月夏季沖繩陽光極強，務必攜帶高係數防曬乳、太陽眼鏡與輕薄防曬罩衫。 3. 許多海景咖啡廳如美濱美國村與古宇利島人氣店舖建議提前於線上預留靠窗海景座位。","generatedAt":1793468037271,"model":"gemini-3.5-flash-lite"}},{"id":"trip_bali","name":"峇里島烏布叢林Villa與懸崖夕陽","locationName":"Bali, Indonesia","lat":-8.5069,"lng":115.2625,"minDays":5,"maxDays":8,"budget":"$$","costEstimate":"~NT$32,000 - 52,000 /人","seasons":["spring","summer","autumn"],"visited":false,"tags":["#私人泳池Villa","#梯田秘境","#烏魯瓦圖夕陽","#漂浮早餐","#傳統熱石SPA"],"description":"入住被熱帶雨林包圍的私人泳池Villa享用浪漫漂浮早餐，漫步梯田小徑，黃昏在烏魯瓦圖斷崖海景酒吧看印度洋落日。","itinerary":{"summary":"專為Seb與Lynn打造的峇里島慢活浪漫之旅，從烏布幽靜的叢林Villa私密甦醒，到烏魯瓦圖懸崖邊共賞壯麗夕陽，在熱帶微風與燭光晚餐中編織兩人專屬的奢華慢時光。","targetDays":7,"pace":"relaxed","days":[{"day":1,"theme":"叢林私宅・初見烏布的綠意呢喃 🌿","morning":"搭乘直飛班機抵達峇里島伍拉·賴國際機場（DPS），由私人專車接機一路駛入烏布綠意盎然的山谷，抵達隱密的叢林Villa辦理入住 🚗","afternoon":"在Villa無邊際泳池畔享用迎賓下午茶，任由山嵐與蟬鳴洗去飛行疲憊，慵懶地換上度假服裝 🏊‍♀️","evening":"步行至烏布皇宮附近的 Locavore To Go 享用精緻輕食，感受微涼夜風下的巷弄漫步 🌙","coupleHighlight":"在Villa的私人露台上，點一盞香氛蠟燭，並肩聽著遠處蛙鳴與風吹樹葉的沙沙聲，輕輕舉杯慶祝旅程的開始 🥂"},{"day":2,"theme":"藝術靈魂・阿勇河谷的慵懶漫步 🎨","morning":"睡到自然醒，在Villa床上享用漂浮早餐（Floating Breakfast），邊泡水邊品嚐熱帶鮮果與現榨果汁 🍳","afternoon":"前往烏布藝術市場（Ubud Art Market）挑選手工藤編包，隨後落腳於仙氣十足的 Seniman Coffee Studio 啜飲手沖咖啡 ☕","evening":"造訪知名網美餐廳 Pison Ubud，在法式工業風與稻田交織的氛圍中品嚐結合印尼風味的義大利麵 🍝","coupleHighlight":"在咖啡館靠窗的舒適沙發椅上，兩人共讀一本書，偶爾抬頭相視而笑，享受無人打擾的午后靜謐 📖"},{"day":3,"theme":"神聖梯田・德哥拉朗的雙人瑜珈 🧘‍♀️","morning":"清晨前往 Ubud Yoga House 參與戶外雙人瑜珈課程，在晨光與稻田環繞中舒展身心 🌾","afternoon":"驅車前往 Tegalalang Rice Terrace，坐在懸崖邊的 Cafe Tis 雙人躺椅上，俯瞰層疊梯田與椰林風光 🥥","evening":"返回烏布市區，在皇宮對面的 Lotus Café 享用晚餐，欣賞蓮花池畔的傳統爪哇舞蹈表演 💃","coupleHighlight":"在梯田景觀咖啡廳的網紅藤椅上，Seb溫柔地從身後擁著Lynn，合影留下被翠綠山谷包圍的浪漫剪影 📸"},{"day":4,"theme":"南向蔚藍・烏魯瓦圖懸崖漫遊 🌊","morning":"悠閒退房，搭乘專車南下至烏魯瓦圖（Uluwatu），入住能眺望印度洋的懸崖奢華度假村 🚙","afternoon":"前往著名的 Single Fin 懸崖海景餐廳，挑選面海的絕佳座位，迎著強勁海風品嚐冰涼的發泡飲品 🍻","evening":"在懸崖畔的 Sundays Beach Club 踩著細軟白沙，享用腳下點起燭光的無敵海鮮燒烤晚餐 🦐","coupleHighlight":"赤腳漫步在退潮的烏魯瓦圖沙灘上，海浪輕拍腳踝，兩人十指緊扣看著夕陽漸漸沒入印度洋海平面 🌅"},{"day":5,"theme":"秘境海灘・金巴蘭的落日情詩 🏖️","morning":"在度假村的無邊際海景泳池戲水，享受私密且慵懶的早晨，讓陽光親吻肌膚 ☀️","afternoon":"前往隱密美麗的 Melasti Beach，在純白沙灘與壯麗石灰岩壁下，度過安靜的午後日光浴時光 🐚","evening":"移步至金巴蘭灣（Jimbaran Bay）老牌海鮮餐廳，在沙灘上的雙人燭光桌上品嚐碳烤大蝦與魚貨 🕯️","coupleHighlight":"當金巴蘭天空被染成夢幻的紫紅色時，兩人坐在沙灘餐桌旁，分食一口帶有炭烤香氣的鮮甜明蝦 🦐"},{"day":6,"theme":"私人放鬆・海島最後的奢華Spa 💆‍♀️","morning":"睡到自然醒，在房內享用豐盛的歐陸早午餐，隨後預約度假村內的頂級Spa中心 🌿","afternoon":"享受長達兩小時的巴里島傳統雙人Lulur精油按摩與花瓣浴，徹底釋放全身壓力 🌸","evening":"前往水明漾（Seminyak）時尚街區的 Merah Putih 餐廳，在挑高挑脊與垂直採光的奢華空間享用現代印尼料理 🍷","coupleHighlight":"在被花瓣覆蓋的巨型浴缸中，Seb親手為Lynn遞上一杯冰鎮香檳，享受專屬於兩人的微醺浪漫 🥂"},{"day":7,"theme":"珍藏記憶・帶著熱帶微風返回台北 ✈️","morning":"把握最後時光在Villa泳池畔拍下晨光合照，細細品嚐最後一碗道地的印尼炒飯（Nasi Goreng） 🍛","afternoon":"前往當地精品選物店選購手工香氛與咖啡豆作為伴手禮，隨後由專車接送前往機場 🛍️","evening":"搭乘直飛航班返回台灣，帶著滿滿的叢林芬多精與懸崖夕陽記憶，結束完美的蜜月旅程 🌙","coupleHighlight":"在飛機起飛升空、俯瞰峇里島夜景時，兩人自然地靠著彼此肩膀，回味這七天裡只屬於彼此的低語與笑聲 ✈️"}],"mustTryFoods":["烏布髒鴨飯 (Bebek Betutu / Crispy Duck)","印尼傳統炒飯 (Nasi Goreng)","金巴蘭沙灘碳烤海鮮 (Jimbaran Seafood BBQ)","巴里島傳統風味烤豬飯 (Babi Guling)"],"tips":"1. 台灣旅客前往印尼免觀光簽證（VoA需注意護照效期須在6個月以上），建議出發前於線上預先填寫電子海關申報單（ECD）以加快出關速度。2. 峇里島南部（烏魯瓦圖與水明漾一帶）交通容易塞車，強烈建議透過Klook或包車App預約中文司機，既省時又舒適。3. 烏布叢林蚊蟲較多，建議攜帶天然成分防蚊液與輕薄透氣的長袖衣物。","generatedAt":1793468054882,"model":"gemini-3.5-flash-lite"}},{"id":"trip_chiangmai","name":"清邁山城文青慢活與水燈夜市巡禮","locationName":"Chiang Mai, Thailand","lat":18.7883,"lng":98.9853,"minDays":4,"maxDays":6,"budget":"$","costEstimate":"~NT$16,000 - 26,000 /人","seasons":["winter","autumn","spring"],"visited":false,"tags":["#寧曼路咖啡","#清邁夜市","#平價泰式按摩","#水燈節","#大象友善營"],"description":"在寧曼路林蔭小巷穿梭特色文青咖啡館，夜晚漫步手作夜市品嚐在地小吃，體驗平價又舒壓的雙人泰式草本SPA。","itinerary":{"summary":"為 Seb 與 Lynn 量身打造的清邁慢活之旅，漫步於古城文青巷弄與河畔微風中，在寺廟燭光與水燈祈願裡，共度不疾不徐的浪漫時光。","targetDays":5,"pace":"relaxed","days":[{"day":1,"theme":"古城初見・尼曼區漫步與山景夕陽 ☕","morning":"搭乘直飛航班抵達清邁國際機場，專車接送至尼曼路（Nimman）質感設計旅店辦理入住，稍作梳洗，享受無壓力的慵懶早晨。","afternoon":"漫步於 One Nimman 紅磚文青街區，造訪在地獨立咖啡館 Ristr8to 啜飲世界級拿鐵，挑選手作香氛選物。","evening":"前往 Maya 百貨頂樓的 Vista Deck，點一杯微醺調酒，依偎著欣賞素貼山（Doi Suthep）背後漸層的粉紫色日落。","coupleHighlight":"在頂樓露台的微風中輕輕碰杯，互道抵達清邁的喜悅，並肩俯瞰點燈後的璀璨夜景 🍸"},{"day":2,"theme":"古城寺廟與慢活手作・護城河畔午茶 🌿","morning":"睡到自然醒，享用豐富的泰式早午餐。隨後前往帕辛寺（Wat Phra Singh）欣賞精緻的蘭納建築，感受古城的寧靜晨光。","afternoon":"造訪 Tha Phae Gate 附近的文青聚落，走入隱密巷弄的手作陶藝坊，挑選一對屬於兩人的手作陶瓷對杯。","evening":"坐在萍河（Ping River）畔的 The Gallery 餐廳，在百年大樹下享用精緻的當代泰北燭光晚餐。","coupleHighlight":"河畔燭光搖曳下，交換剛選好的陶杯承諾，在蟲鳴與水流聲中輕輕互扣雙手 🕯️"},{"day":3,"theme":"山林森呼吸・湄林秘境咖啡與雙人芳療 🍃","morning":"乘車前往清邁西北方的湄林（Mae Rim）山區，探訪藏身於梯田與綠意間的 Zofeen Cafe，被群山環繞的景致治癒。","afternoon":"返回市區，前往頂級水療中心 Fah Lanna Spa，享受 2 小時的蘭納古法草本精油雙人按摩，徹底放鬆身心。","evening":"在寧靜的巷弄內享用溫潤的泰北咖哩麵（Khao Soi），隨後散步回旅店，享受無行程的私密夜晚。","coupleHighlight":"在芳療室飄散著青草香氣的私密空間裡，兩人沈浸於溫熱草本球輕壓的舒暢，牽手步入微涼夜色 🌸"},{"day":4,"theme":"浪漫水燈節・古城祈願與夜市巡禮 🏮","morning":"悠閒享用飯店早餐，午後前往瓦洛洛市場（Warorot Market）選購棉麻情侶服飾與精緻手工藤編包。","afternoon":"造訪柴迪隆寺（Wat Chedi Luang），在宏偉的古老佛塔下感受歷史的沉靜，並在樹蔭下靜靜坐著閱讀或談心。","evening":"傍晚前往萍河畔與古城護城河，參與水燈節（Yi Peng）的浪漫儀式，親手將點燃的水燈放入水中。","coupleHighlight":"在水燈燭光倒映彼此笑臉的瞬間，閉上雙眼在心中默許未來心願，十指緊扣看著水燈緩緩漂向遠方 ✨"},{"day":5,"theme":"晨光市集・依依不舍的漫調告別 🥐","morning":"造訪清邁大學後門的 Baan Kang Wat 藝術村，在綠意盎然的木屋聚落中挑選獨立設計師明信片。","afternoon":"選一家庭院咖啡館（如 Fern Forest Cafe）享用最後一場法式可頌與冰泰奶，整理這幾天累積的甜蜜戰利品。","evening":"帶著滿滿的慢活回憶與伴手禮，專車前往清邁機場，搭機返回台灣。","coupleHighlight":"在機場登機口前共享最後一杯泰式奶茶，回味這幾天不用看手錶的慵懶與深情 ✈️"}],"mustTryFoods":["Khao Soi (濃郁椰香泰北黃咖哩雞肉麵)","Sai Oua (香茅風味炭烤泰北香腸)","Nam Phrik Ong (酸甜番茄豬肉沾醬佐新鮮時蔬)","Mango Sticky Rice (椰漿香芒糯米飯)"],"tips":"建議台灣旅客事先下載 Grab 或 Bolt App 以利叫車；水燈節期間機票與飯店務必提前三個月預定；清邁日夜溫差較大，早晚山區微涼，請務必攜帶輕便外套與防蚊液。","generatedAt":1793468057782,"model":"gemini-3.5-flash-lite"}},{"id":"trip_kinmen","name":"金門戰地洋樓與古厝星空漫遊","locationName":"Kinmen, Taiwan","lat":24.4493,"lng":118.3766,"minDays":3,"maxDays":4,"budget":"$","costEstimate":"~NT$9,500 - 16,000 /人","seasons":["autumn","spring","winter"],"visited":false,"tags":["#水頭洋樓","#翟山坑道","#慈湖落日","#金門高粱","#閩南古厝"],"description":"漫步得月樓與水頭聚落典雅洋樓群，在翟山坑道聆聽波光迴響，傍晚在慈湖欣賞廈門天際線壯麗落日，入住百年閩南古厝夜觀星空。","itinerary":{"summary":"專為Seb與Lynn打造的金門慢旅，在閩南燕尾與高粱田間漫步，於落日餘暉下共享微光，享受不趕行程的溫柔時光。🌾🕊️","targetDays":4,"pace":"relaxed","days":[{"day":1,"theme":"燕尾初相見・古厝聚落漫步 🏮","morning":"從台灣搭機飛抵金門，悠閒領取租賃機車，入住水頭聚落的百年閩南古厝民宿，感受歲月靜好的沉澱氣息。","afternoon":"午後漫步於水頭聚落，欣賞精雕細琢的「得月樓」與洋樓風華，隨性造訪古厝裡的質感咖啡館，品嚐手沖咖啡與金門在地手作甜點 ☕。","evening":"在聚落石板路上散步至在地小餐館，享用道地的金門廣東粥與酥脆油條，感受微涼夜風中的寧靜古意。","coupleHighlight":"牽手坐在百年古厝的院落紅磚椅上，分食一份溫熱的芋頭餅，聽著微風穿過燕尾屋脊的沙沙聲 🍂"},{"day":2,"theme":"湖光倒影・慈堤夕陽微光 🌅","morning":"睡到自然醒，前往金寧鄉享用豐盛的閩式燒餅配熱豆漿，隨後前往漫步於慈湖畔，觀賞水面如鏡的療癒倒影 🌊。","afternoon":"午後躲進寧安老街上的獨立書店或特色茶館，兩人窩在一起翻看島嶼選書，享受安靜而親密的午後時光 📖。","evening":"黃昏時分騎車前往慈堤三角堡，依偎著觀賞金門最著名的橘紅落日沒入海平線，霞光映照在廢棄戰車與碉堡上。","coupleHighlight":"在慈堤夕陽下的木棧道旁並肩而坐，靜靜看著海鷗飛過金門大橋剪影，交換一杯熱可可 ☕"},{"day":3,"theme":"麥田與風獅爺・文青聚落尋光 🌾","morning":"慵懶地享用早午餐後，展開尋找可愛風獅爺的浪漫小旅行，穿梭於金沙鎮的金波麥浪與小徑之間 📸。","afternoon":"午後造訪沙美摩洛哥（沙美老街），在土黃色廢墟美學中捕捉復古文青風合照，隨後到附近老宅咖啡館喝下午茶。","evening":"晚餐前往后丰港或金城鎮上品嚐全牛大餐或炒泡麵，享受濃郁溫潤的在地滋味。","coupleHighlight":"在金沙鎮的高粱田小徑旁停下車，迎著微風相視而笑，用底片相機幫彼此拍下最自然的笑顏 📷"},{"day":4,"theme":"島嶼告別・湖下海堤呢喃 🕊️","morning":"睡個飽覺後退房，前往金城模範街採買伴手禮（如貢糖、牛肉乾、手工麵線），感受古老街道的熱鬧人情味。","afternoon":"在登機前保留最後一段浪漫，坐在湖下海堤旁的玻璃屋咖啡館，望著金門大橋喝一杯拿鐵，為旅程畫下句點 ☕。","evening":"搭乘班機返回台灣，行李箱裝滿金門的陽光、海風與深刻的雙人回憶。","coupleHighlight":"在湖下海堤的長椅上靠著彼此肩膀，聽著海浪輕拍堤岸，輕聲約定下次還要一起來金門看星星 🌟"}],"mustTryFoods":["金門廣東粥配油條（粥糜化無米，口感綿密滑順）","閩式燒餅（甜鹹口味層次分明，酥脆掉渣）","高粱牛肉麵（湯頭濃郁，牛肉軟嫩入味）","金門芋頭冰（綿密香濃的烈嶼小金門芋頭甜品）"],"tips":"1. 推薦租機車雙載環島，最能隨性停留在路邊的麥田與海堤。 2. 春秋季早晚溫差大且容易起霧，請務必攜帶防風外套與圍巾。 3. 入住閩南古厝民宿需提前數月預訂，感受最具特色的在地文化。","generatedAt":1793468065958,"model":"gemini-3.5-flash-lite"}},{"id":"trip_penghu","name":"澎湖花火海風與雙心石滬跳島巡禮","locationName":"Penghu, Taiwan","lat":23.5711,"lng":119.5793,"minDays":3,"maxDays":5,"budget":"$","costEstimate":"~NT$11,000 - 19,000 /人","seasons":["spring","summer"],"visited":false,"tags":["#澎湖花火節","#七美雙心石滬","#奎壁山摩西分海","#山水沙灘","#仙人掌冰"],"description":"初夏在觀音亭欣賞海灣綻放的絢爛花火，騎車前往七美見證雙心石滬的浪漫誓言，在奎壁山踏著退潮礫石路感受摩西分海奇景。","itinerary":{"summary":"專為Seb與Lynn打造的澎湖漫活浪漫之旅，以海風、跳島與絢爛花火交織，放慢步伐在蔚藍海岸與私房海景咖啡館中共享兩人時光。","targetDays":4,"pace":"relaxed","days":[{"day":1,"theme":"抵達菊島・漫步老街與夕陽海堤 🏮","morning":"搭乘國內航班自台灣飛抵澎湖馬公機場，前往市區文青旅店辦理入住，稍作歇息調整心情 ✈️","afternoon":"午後漫步於中央老街，穿梭四百年的四眼井與摸乳巷，在「藍洞 Aquadan」或巷弄手作小店挑選紀念品 ☕","evening":"散步至觀音亭海濱，坐在岸邊看夕陽將天空染成粉橘色，等待夜幕低垂時絢麗的澎湖海上花火節綻放 🎆","coupleHighlight":"在燦爛的花火夜空下輕輕牽起手，耳邊伴隨澎湃的浪聲與煙火震撼，交換一個溫柔的擁抱 🎇"},{"day":2,"theme":"跳島漫遊・雙心石滬與蔚藍海灣 💙","morning":"睡到自然醒後，搭乘舒適客船前往七美島，沿著浪漫的環島公路欣賞龍埕海蝕地形與小臺灣 🛥️","afternoon":"造訪象徵永恆愛情的「雙心石滬」，在蔚藍漸層的海水旁吹著海風，隨後於島上浪漫海景咖啡座享用冰涼仙草冰 🍧","evening":"搭船返回馬公市區，卸下一日疲憊，在在地知名海鮮餐廳「鮮定味生猛海鮮」享用現撈龍蝦與鮮美海膽炒蛋 🦞","coupleHighlight":"在七美的雙心石滬旁，背對著蔚藍大海，對彼此許下攜手看遍世界美景的浪漫承諾 🌊"},{"day":3,"theme":"秘境沙灘・奎壁山摩西分海與夕陽漫漫 🏖️","morning":"享受一個沒有鬧鐘的早晨，在民宿享用澎湖道地鮮魚湯早餐，午後前往北環線探索壯麗的柱狀玄武岩地景 🪨","afternoon":"造訪奎壁山「摩西分海」奇景，趁著退潮時牽手走過漫長的海中步道，感受大自然的奇妙奧秘 ✨","evening":"前往山水沙灘旁的「風櫃聽濤」吹海風，隨後在沙灘邊的浪漫餐酒館「Maru Cafe」啜飲特調，聽著輕柔爵士樂 🍸","coupleHighlight":"赤腳踩在山水沙灘細緻的白砂上，任由浪花輕輕拍打腳踝，並肩看著夕陽沒入海平面 🌅"},{"day":4,"theme":"甜點時光・菊島告別與甜蜜返航 ✈️","morning":"悠閒享用早午餐，前往馬公市區的「澎湖故事妻」或質感選物店挑選伴手禮，細細品味澎湖的慢步調 🎁","afternoon":"造訪隱身巷弄的法式甜點店「菊島法式甜點」，品嚐融入仙人掌與風茹茶風味的精緻慕斯蛋糕 🍰","evening":"帶著滿滿的浪漫回憶與伴手禮前往馬公機場，搭乘班機返回台灣，結束甜蜜的海島假期 🛫","coupleHighlight":"在機場候機時，兩人一起翻看這四天拍下的拍立得照片，回味彼此相視而笑的溫暖瞬間 📸"}],"mustTryFoods":["澎湖冰品仙人掌雪花冰","新鮮現蒸澎湖小管與小卷米粉","馬公老街外垵刈包與黑糖糕","鮮美海膽炒蛋與土魠魚羹"],"tips":"1. 澎湖花火節期間機票與住宿務必提前3-5個月預訂；2. 七美跳島船班易受海象影響，請備妥暈船藥並隨時關注航班異動；3. 夏季陽光強烈，防曬乳（建議選用海洋友善配方）、太陽眼鏡與薄外套為必備單品。","generatedAt":1793468074271,"model":"gemini-3.5-flash-lite"}},{"id":"trip_xiaoliuqiu","name":"小琉球珊瑚海龜共游與落日環島","locationName":"Xiaoliuqiu, Taiwan","lat":22.3424,"lng":120.3703,"minDays":2,"maxDays":3,"budget":"$","costEstimate":"~NT$4,500 - 8,500 /人","seasons":["all"],"visited":false,"tags":["#海龜共游","#花瓶岩","#落日亭夕陽","#威尼斯沙灘","#SUP立槳"],"description":"戴上面鏡在花瓶岩清澈見底的海水中與溫柔海龜同游，傍晚在落日亭看橘紅晚霞墜入台灣海峽，夜晚吹著溫暖海風享受島嶼慢步調。","itinerary":{"summary":"為Seb與Lynn量身打造的小琉球慢活之旅，避開人潮乘風破浪與海龜共舞，在落日餘暉下於海景咖啡廳啜飲微醺，享受專屬兩人的浪漫蔚藍時光。","targetDays":3,"pace":"relaxed","days":[{"day":1,"theme":"蔚藍登島・美景海景咖啡廳漫步 🌊","morning":"東港碼頭搭乘客船前往小琉球，抵達後由民宿專人接送至充滿海島風情的無敵海景民宿辦理入住，享受慵懶的迎賓海草冰沙。","afternoon":"漫步至「落日亭」附近的質感海景咖啡廳，挑選一個面海的雙人沙發座，一邊品嚐手沖咖啡與現烤鬆餅，一邊看著波光粼粼的海面。","evening":"散步前往「琉球魅市集」或在地人氣海鮮餐廳，享用鮮甜的海膽炒飯與現烤鮮蚵，感受小島夜晚的徐徐海風。","coupleHighlight":"在落日亭的木棧道上並肩而坐，靜靜看著夕陽將海平面染成浪漫的粉橘色，輕輕分享彼此耳機裡的音樂。"},{"day":2,"theme":"海龜共游・夕陽環島浪漫漫遊 🐢","morning":"睡到自然醒後享用精緻早午餐，隨後由專業教練帶領，前往花瓶岩或美人洞海域進行溫柔的深潛或浮潛，與野生海龜悠遊於珊瑚礁花園中。","afternoon":"午後換上輕便情侶裝，租借電動機車沿著環島公路漫遊，造訪充滿神祕氣息的「美人洞」海景木棧道，隨性停留於路邊的冰店品嚐芒雪冰。","evening":"造訪島上最浪漫的露天餐酒館，在星空與串燈下享用現烤BBQ與特調調酒，享受專屬兩人的微醺夜。","coupleHighlight":"在蔚藍水下牽著彼此的手，與探出頭換氣的綠蠵龜擦身而過，交換一個隔著面鏡的驚喜眼神。"},{"day":3,"theme":"晨光秘境・漫步漫嚐伴手禮回程 🌿","morning":"清晨前往「厚石群礁」一帶欣賞朝陽，看陽光灑落奇岩海岸。隨後回民宿享用手作早餐，把握退房前的最後悠閒時光。","afternoon":"造訪島上文青手作選物店與人氣起司餅老店，挑選精緻的貝殼紀念品與現炸爆漿起司捲作為此行的甜蜜見證，隨後搭船返回東港。","evening":"平安抵達東港碼頭，搭乘高鐵或專車返回溫暖的家，將滿滿的海洋記憶收進行李。","coupleHighlight":"在返回本島的客船甲板上，迎著海風緊緊相擁，回味這三日無拘無束的島嶼私密時光。"}],"mustTryFoods":["小琉球爆漿黑糖天使厚片","海膽醬海鮮炒飯","手工現做起司捲","海草冰沙與芒雪冰"],"tips":"建議提早兩週預訂東港至小琉球的來回船票與島上電動機車；小琉球紫外線強烈，請務必攜帶環保防曬乳、太陽眼鏡與輕便薄外套；浮潛裝備與教練建議透過民宿代訂，能享有更流暢的私房潛點安排。","generatedAt":1793468076750,"model":"gemini-3.5-flash-lite"}},{"id":"trip_lanyu","name":"蘭嶼達悟拼板舟與太平洋玻璃海秘境","locationName":"Lanyu, Taiwan","lat":22.0564,"lng":121.5508,"minDays":4,"maxDays":6,"budget":"$","costEstimate":"~NT$13,000 - 22,000 /人","seasons":["spring","summer"],"visited":false,"tags":["#達悟拼板舟","#青青草原夕陽","#東清灣日出","#玻璃海浮潛","#地下屋文化"],"description":"清晨在東清灣迎接台灣第一道海上日出，在青青草原懸崖邊吹風看海浪拍打奇岩，潛入果凍般透明的太平洋海底欣賞繽紛珊瑚世界。","itinerary":{"summary":"為Seb與Lynn量身打造的蘭嶼湛藍逃逸之旅，在透徹如玻璃的太平洋海域與達悟拼板舟的古老木香中，享受無拘無束的慵懶慢活。","targetDays":5,"pace":"relaxed","days":[{"day":1,"theme":"航向蔚藍・抵達惡靈退散的神秘之島 ✈️","morning":"搭乘德安航空小飛機從台東起飛，俯瞰窗下漸層的海藍色果凍海，平穩降落於蘭嶼機場 🛩️。","afternoon":"入住椰油部落質感海景民宿，卸下行李後前往「雯雯芋頭冰」享用招牌芋頭冰沙，看著窗外波光粼粼的港口放空 🍧。","evening":"漫步至椰油國小，坐在緊鄰大海的司令台上欣賞夕陽將海面染成溫柔的粉橘色 🌅。","coupleHighlight":"在海風吹拂的椰油堤防上，兩人大口分享一杯冰涼的飛魚卵奶茶，交換初見蘭嶼的驚嘆 🥤"},{"day":2,"theme":"拼板舟的呢喃・野銀地下屋時光倒流 🛶","morning":"自然睡到自然醒，前往「AER 咖朵咖啡」享用手沖咖啡與輕食，享受窗外無邊際的蔚藍海景 ☕。","afternoon":"由在地達悟嚮導帶領，預約體驗傳統「拼板舟體驗」，兩人同心協力划向透徹見底的情人湖海域 🌊。","evening":"探訪野銀舊部落地下屋，聆聽石板與達悟祖先建築智慧的故事，感受時間彷彿在此凍結 🛖。","coupleHighlight":"在拼板舟上輕輕牽起彼此的手，任由小船隨太平洋的蔚藍湧浪溫柔搖晃，感受彼此的脈搏 🤝"},{"day":3,"theme":"玻璃海秘境・東清灣的浪聲與星空 🌌","morning":"慵懶地前往東清部落，造訪「Do Van Wa 多瓦哇」享用早午餐，慵懶地看著羊群在屋頂上漫步 🐐。","afternoon":"前往東清祕密海灘（情人洞附近），在天然海蝕洞的陰涼處泡著清涼的海水，細數水底悠遊的熱帶魚 🐠。","evening":"造訪「東清夜市」品嚐風味小點，隨後躺在東清灣的碎石灘上，仰望毫無光害的滿天銀河與流星 ✨。","coupleHighlight":"在東清灣無垠的星空下並肩躺著，輕聲許下屬於兩人的浪漫願望，讓海浪聲成為最輕柔的背景音樂 🌠"},{"day":4,"theme":"島嶼的最高處・漫步朗島的藝術聚落 🎨","morning":"睡到自然醒後慢遊朗島部落，欣賞錯落有致的拼板舟晾船台與達悟傳統建築，造訪極具設計感的獨立書店 📚。","afternoon":"驅車前往氣象觀測站，站在島嶼制高點俯瞰雙邊海灣的壯麗全景，吹拂360度無死角的山海微風 🌬️。","evening":"預約「席巴達風味餐廳」享用精緻的飛魚創意晚餐，細細品嚐島嶼在地食材的鮮美滋味 🐟。","coupleHighlight":"在氣象觀測站的白色圓球旁，背對著太平洋壯闊的懸崖峭壁，留下兩人最深情依偎的剪影合照 📸"},{"day":5,"theme":"最後的浪花・帶著蔚藍記憶返回本島 🐚","morning":"在「迦南園」享用美味早餐，把握最後時光在紅頭部落選購手作紀念貝殼飾品與明信片 💌。","afternoon":"帶著依依不舍的心情前往蘭嶼機場，搭乘班機飛回台東，結束這場純淨浪漫的玻璃海假期 ✈️。","coupleHighlight":"在候機室的窗邊，兩人交換這幾天寫給彼此的明信片，為這趟島嶼私密之旅畫下完美句點 ✍️"}],"mustTryFoods":["飛魚卵炒飯","芋頭冰沙","風味飛魚一夜干","林投果汁"],"tips":"1. 蘭嶼船票或德安航空機票務必提早兩個月搶訂，尤其是夏季旺季。\n2. 島上騎乘機車為最佳移動方式，請務必注意防曬並隨身攜帶環保水壺。\n3. 尊重達悟族文化，拍攝拼板舟、地下屋或當地居民前務必先徵得同意。","generatedAt":1793468266949,"model":"gemini-3.5-flash-lite"}},{"id":"trip_tainan","name":"台南古都巷弄漫步與米其林甜點小吃","locationName":"Tainan, Taiwan","lat":22.9997,"lng":120.227,"minDays":2,"maxDays":4,"budget":"$","costEstimate":"~NT$4,000 - 8,000 /人","seasons":["all"],"visited":false,"tags":["#神農街文青巷","#溫體牛肉湯","#奇美博物館","#安平夕陽","#四草綠色隧道"],"description":"牽手散步於神農街古色古香的燈籠小巷，清晨品嚐溫體現沖牛肉湯與傳統碗粿，午後走入奇美博物館凡爾賽宮殿與四草紅樹林隧道。","itinerary":{"summary":"為 Seb 與 Lynn 打造的台南慢旅，穿梭於府城老宅巷弄間，品味米其林推薦的細膩甜點與在地小吃，享受不趕時間的慵懶浪漫時光。","targetDays":3,"pace":"relaxed","days":[{"day":1,"theme":"府城老宅微光・巷弄裡的午茶絮語 🏮","morning":"睡到自然醒後，悠閒漫步至中西區國華街一帶，品嚐在地人推薦的清燙牛肉湯與鮮甜肉燥飯，揭開台南早晨的序幕。","afternoon":"走進神農街的百年老屋改造咖啡館，點一份精緻的法式千層蛋糕與手沖咖啡，感受舊時光與現代美學交織的寧靜。","evening":"傍晚漫步至赤崁樓周邊，在燈籠微光下品嚐米其林必比登推薦的擔仔麵與虱目魚皮湯，隨後散步於巷弄感受微涼晚風。","coupleHighlight":"午後在老宅窗邊並肩坐著，兩人共嚐一份微酸的檸檬塔，交換彼此眼中的台南舊影 🍋"},{"day":2,"theme":"文藝綠意漫旅・府城私房甜點巡禮 🌿","morning":"慵懶享用飯店早餐後，前往台南美術館二館欣賞純白建築的光影流動，感受現代藝術的洗禮。","afternoon":"轉往幸運草般的府城巷弄，探訪隱身民宅的米其林入選甜點店，細細品嚐結合在地食材的創意冰品與手作洋菓子。","evening":"夜幕低垂時，前往安平運河畔散步，看著水面倒影燈光，享受沒有喧擾的雙人靜謐時光。","coupleHighlight":"在運河畔的微風中十指緊扣散步，分享一支濃郁的義式手工冰淇淋，看夕陽沒入水面 🍦"},{"day":3,"theme":"日式古蹟巡禮・緩步告別府城 🍃","morning":"睡個飽覺後退房，前往「台南知事官邸」參觀，在紅磚拱廊下拍下充滿復古文藝氣息的合照。","afternoon":"在東區漫步，造訪隱身綠意中的質感茶屋，細細品飲台灣在地好茶，配上一塊手工達克瓦茲，為假期畫下優雅句點。","evening":"搭乘高鐵返回台灣各地，帶著滿滿的甜點香氣與巷弄記憶，甜蜜賦歸。","coupleHighlight":"在日式老建築的庭院綠蔭下，輕輕靠著彼此肩膀，許下下次再訪台南的溫柔約定 ☕"}],"mustTryFoods":["文章牛肉湯","阿裕牛肉涮涮鍋","深藍咖啡館千層蛋糕","富盛號碗粿"],"tips":"台南巷弄多為單行道且狹窄，建議以步行漫步或租借YouBike穿梭最為浪漫便利；部分米其林甜點名店建議於出發前兩週完成線上預約，以確保窗邊兩人座位。","generatedAt":1793468085726,"model":"gemini-3.5-flash-lite"}},{"id":"trip_sunmoonlake","name":"日月潭全球最美單車道與水映晨霧之旅","locationName":"Nantou, Taiwan","lat":23.8683,"lng":120.9158,"minDays":2,"maxDays":3,"budget":"$","costEstimate":"~NT$8,500 - 16,000 /人","seasons":["all"],"visited":false,"tags":["#向山水上單車道","#湖畔晨霧","#日月潭紅茶","#水社碼頭遊船","#文武廟景觀"],"description":"清晨沿著被譽為全球最美的向山水上自行車道輕踩單車，看晨霧如輕紗般籠罩碧綠湖面，品味濃郁台茶18號紅玉紅茶與湖景下午茶。","itinerary":{"summary":"為 Seb 與 Lynn 量身打造的水社湖畔慢旅，在湖光山色與裊裊晨霧中，以無壓的漫步與私房咖啡館，收藏日月潭最純粹的雙人倒影。","targetDays":3,"pace":"relaxed","days":[{"day":1,"theme":"水社初見・湖畔漫步與山景下午茶 ☕","morning":"搭乘高鐵轉乘台灣好行直達日月潭水社遊客中心，入住湖景飯店，在房間陽台慵懶享用迎賓茶點，看湖面波光粼粼。","afternoon":"漫步至水社碼頭旁的「湖の怪物」咖啡館，品嚐造型精緻的紅豆草餅與手沖咖啡，享受窗外的湖水綠意。","evening":"在涵碧步道散心，隨後於水社街上的「湖畔平價小吃」品嚐在地總統魚酥與邵族竹筒飯，感受徐徐晚風。","coupleHighlight":"牽手走在沒有遊客喧擾的涵碧步道木棧道上，借著昏黃路燈，分享一顆剛買的熱騰騰茶葉蛋。"},{"day":2,"theme":"晨光雙人倒影・向山美學建築漫遊 🛶","morning":"睡到自然醒，清晨前往水社親水步道捕捉平靜水面上的山巒倒影，租借雙人協力電動船，在水面上享受無人打擾的寧靜時刻。","afternoon":"造訪建築大師團紀彥設計的「向山行政暨遊客中心」，在清水模廊道下靜靜坐著，眺望無邊際水池與日月潭交織的絕景。","evening":"前往日月潭大飯店湖畔餐廳享用精緻的浪漫晚餐，落地窗外是打上燈光的浪漫夜景。","coupleHighlight":"在向山懸臂式觀景台的延伸平台上，背對湖光山色，拍下一張兩人相依偎的剪影合照。"},{"day":3,"theme":"茶鄉漫時光・伊達邵老街隨心漫遊 🍵","morning":"慵懶退房後，搭乘遊艇前往伊達邵碼頭，避開人潮，轉入巷弄裡的「日月茶館」品嚐在地手採紅玉紅茶。","afternoon":"在伊達邵老街品嚐手工小米麻糬與烤香菇，坐在湖畔長椅上餵著微風，為這趟旅程畫下句點。","evening":"從水社搭乘客運返回台中高鐵站，帶著滿滿的茶香與湖景記憶，愜意返回台北溫暖的家。","coupleHighlight":"在茶館榻榻米座位上，兩人並肩品評著台茶18號的肉桂與薄荷香氣，交換彼此這三天的最愛時刻。"}],"mustTryFoods":["日月潭阿婆茶葉蛋","邵族特色竹筒飯","台茶18號紅玉紅茶拿鐵","在地總統魚酥"],"tips":"建議購買「台灣好行日月潭線套票」包含車票與遊船券最為划算；水社與向山步道皆為無障礙木棧道，建議穿著舒適好走的平底鞋；春秋兩季早晚溫差大，記得攜帶輕便防風外套。","generatedAt":1793468089495,"model":"gemini-3.5-flash-lite"}},{"id":"trip_taitung","name":"台東太平洋蔚藍海岸與金黃稻浪縱谷","locationName":"Taitung, Taiwan","lat":22.7583,"lng":121.1444,"minDays":3,"maxDays":5,"budget":"$","costEstimate":"~NT$9,500 - 18,000 /人","seasons":["summer","autumn","spring"],"visited":false,"tags":["#池上伯朗大道","#鹿野高台熱氣球","#三仙台海景","#鐵花村音樂","#太麻里曙光"],"description":"在池上伯朗大道騎單車穿越無垠的金黃稻浪，在鹿野高台看五彩熱氣球在縱谷晨光中升空，夜晚在鐵花村手繪燈海下聽原民歌聲悠揚。","itinerary":{"summary":"為Seb與Lynn量身打造的台東慢活之旅，在太平洋的蔚藍海風與縱谷的金黃稻浪間，享受無拘無束的雙人甜蜜時光。","targetDays":4,"pace":"relaxed","days":[{"day":1,"theme":"山海交會・漫步蔚藍海岸線 🌊","morning":"從台灣出發抵達台東，搭乘專車前往知本老爺酒店辦理入住，在溫泉房內慵懶甦醒，享用精緻的迎賓茶點。","afternoon":"前往東海岸的「都蘭海角咖啡」，選一張面向無垠太平洋的戶外躺椅，靜靜聽海浪拍打礁石，品嚐手沖咖啡。","evening":"在富岡漁港享用現撈海鮮晚餐，隨後漫步於海濱公園，欣賞「向陽樹」公共藝術在夜色中的燈光投影。","coupleHighlight":"深夜在太平洋微風中並肩看星星，輕聲分享彼此對這趟旅程的期待與悸動 ✨"},{"day":2,"theme":"私房海景・漫時光咖啡聚落 ☕","morning":"睡到自然醒，享用緩慢而豐盛的早午餐，隨後沿著台11線公路欣賞海天一色的景致。","afternoon":"造訪藏身在海邊的「w得嚐/is' well」海景咖啡館，兩人合點一份手作甜點，看著浪花翻滾消磨整個下午。","evening":"前往台東市區的「Sice Café & Bar」享用私廚晚餐與微醺調酒，感受台東夜晚獨有的慵懶魔力。","coupleHighlight":"在微醺的浪漫氛圍中，用拍立得為彼此記錄下眼角帶笑的溫柔神情 📸"},{"day":3,"theme":"金黃稻浪・縱谷浪漫漫遊 🌾","morning":"悠閒退房，驅車駛入縱谷公路，沿途欣賞中央山脈與海岸山脈夾夾夾的壯闊田園風光。","afternoon":"漫步於池上「伯朗大道」與「天堂路」，租借一台雙人協力車，穿梭在無邊際的金黃稻浪中迎風而笑。","evening":"入住池上日式風格旅宿，品嚐嚴選在地池上米與在地食材熬煮的無菜單暖心晚餐。","coupleHighlight":"在田野間的木棧道上相擁坐看夕陽沒入山巒，享受四周稻香與蟲鳴的純粹寧靜 🌾"},{"day":4,"theme":"縱谷茶香・甜蜜告別台東 🍵","morning":"在晨光中享用池上米飯糰早餐，前往鹿野高台居高臨下俯瞰整個花東縱谷的綠意盎然。","afternoon":"造訪「永安村」的在地小茶莊，體驗手作紅烏龍茶包，並在茶園旁的木屋裡品嚐茶香戚風蛋糕。","evening":"帶著滿滿的茶香與稻浪記憶，從台東火車站或機場搭乘班次返回台灣溫暖的家。","coupleHighlight":"在回程的車廂或機位上十指緊扣，回味這四天刻意放慢、只屬於彼此的純粹時光 ☕"}],"mustTryFoods":["池上米特製飯糰與在地米貝果","東海岸新鮮生魚片與海鮮料理","鹿野紅烏龍茶與茶香戚風蛋糕","台東在地手作窯烤酸種麵包"],"tips":"建議租賃舒適的休旅車自駕漫遊台11線與台9線，沿途山海景致隨時可停靠；縱谷與海線日夜溫差較大，請務必攜帶防風外套；熱門海景咖啡館建議提前一週線上預約靠窗座位。","generatedAt":1793468091804,"model":"gemini-3.5-flash-lite"}},{"id":"trip_chiayi","name":"嘉義木都森林之歌與檜意森活村漫遊","locationName":"Chiayi, Taiwan","lat":23.48,"lng":120.4491,"minDays":2,"maxDays":3,"budget":"$","costEstimate":"~NT$3,500 - 7,000 /人","seasons":["all"],"visited":false,"tags":["#檜意森活村","#嘉義市立美術館","#文化路夜市","#火雞肉飯","#森林之歌"],"description":"穿上日式浴衣漫步全台最大日式官舍群檜意森活村，造訪綠意盎然的嘉義市立美術館，品嚐油香四溢的正宗火雞肉飯與文化路夜市小吃。","itinerary":{"summary":"為 Seb 與 Lynn 量身打造的木都慢旅，在檜香四溢的日式老屋與林間光影中漫步，享受不趕時間的慵懶浪漫。 🌲✨","targetDays":3,"pace":"relaxed","days":[{"day":1,"theme":"檜木清香・老屋時光漫步 🪵","morning":"睡到自然醒後悠閒抵達嘉義，前往全台最大的日式建築群「檜意森活村」，牽手漫步於保留完好的百年黑瓦木屋與蒼鬱老樹之間，感受時光放慢的靜謐氣息。 🏡","afternoon":"隨性走入園區內的文青選物店與獨立書店，挑選一張明信片；接著落腳於「森咖啡」，在日式老宅的木質窗櫺旁，品嚐手沖咖啡與精緻手作洋菓子。 ☕🍰","evening":"晚餐散步至鄰近的「林聰明沙鍋魚頭」品嚐在地經典美味，夜裡漫步於燈光映襯下的文化路商圈，感受在地人情味與熱鬧氛圍。 🍲🏮","coupleHighlight":"在午後斜陽灑落的檜木廊道下，兩人共撐一把傘，細嗅空氣中淡雅的扁柏清香 🍃"},{"day":2,"theme":"森林之歌・光影藝術交織 🎶","morning":"享受飯店的慵懶早餐，午後前往由黃敏捷設計的巨型地景藝術「森林之歌」，欣賞藤編與木材交織出的奇幻穹頂，感受城市中的森林綠洲。 🌳","afternoon":"轉往「嘉義市立美術館（美術館咖啡廳omelet）」歇息，欣賞舊菸酒倉庫華麗轉身為絕美玻璃帷幕建築，在藝術氛圍中享受午後私密對話。 🖼️🥂","evening":"前往隱身於巷弄內的預約制浪漫餐酒館「Bar Onion」，共享主廚特製的微醺料理與創意調酒。 🍸🕯️","coupleHighlight":"傍晚在「森林之歌」的藤編蛋形隧道內，透過交錯的光影捕捉彼此笑靨，並肩聆聽微風穿過木條的輕柔聲響 🎵"},{"day":3,"theme":"鐵道記憶・職人手作告別 🚂","morning":"漫步至「阿里山林業鐵路車庫園區」，近距離觀賞退役的骨董蒸汽火車，感受台灣林業輝煌時期的浪漫軌跡。 🚂🛤️","afternoon":"造訪「檜意森活村」內的手作木藝坊，挑選一對職人手作的檜木筷子作為此行的紀念信物，隨後在附近的文青茶館「昭和J11咖啡館」啜飲台灣特選高山茶。 🍵🥢","evening":"帶著滿滿的木都香氣與相機裡的甜蜜影像，從容搭乘高鐵或火車返回台灣溫暖的家。 🌅💖","coupleHighlight":"在返程前夕的茶館靠窗座位，交換彼此這三天收集到的微小感動與未來旅行的約定 💌"}],"mustTryFoods":["林聰明沙鍋魚頭","檜意森活村手作洋菓子","昭和J11咖啡館台灣高山茶","嘉義在地火雞肉飯"],"tips":"建議搭乘高鐵至嘉義站後轉乘BRT公車或計程車直達市區；檜意森活村及熱門咖啡廳週末人潮較多，建議提前預約或避開尖峰時段；隨身攜帶輕便環保袋，方便採買木製紀念品與在地伴手禮。","generatedAt":1793468100840,"model":"gemini-3.5-flash-lite"}},{"id":"trip_alishan","name":"阿里山高山神木鐵道與祝山日出雲海","locationName":"Alishan, Chiayi","lat":23.5113,"lng":120.8035,"minDays":2,"maxDays":3,"budget":"$","costEstimate":"~NT$8,500 - 16,500 /人","seasons":["spring","autumn","winter"],"visited":false,"tags":["#祝山日出火車","#千年紅檜神木","#雲海晚霞","#春季櫻花季","#高山烏龍茶"],"description":"凌晨搭乘復古紅色小火車前往祝山看雲海翻騰間金光萬道，漫步巨木群棧道呼吸千年紅檜芬多精，春天更有如雪飄落的櫻花鐵道美景。","itinerary":{"summary":"為Seb與Lynn量身打造的阿里山浪漫慢旅，在百年高山鐵道的竹林與雲海簇擁下，以暖心山茶與日出曙光，編織專屬兩人的高山私密浪漫時光。","targetDays":3,"pace":"relaxed","days":[{"day":1,"theme":"雲端初相見・森林芬多精與山茶漫步 🌲","morning":"從台灣出發搭乘台灣好行或自駕抵達阿里山國家森林遊樂區，於園區入口處的「山賓餐廳」享用熱騰騰的石頭火鍋，暖化高山微涼的空氣 🍲。","afternoon":"入住阿里山賓館歷史館，午後漫步於「沼平公園」與詩意盎然的「天空之橋」，在落羽松與櫻花步道間享受無人的寧靜森林浴 🍂。","evening":"傍晚轉往「阿里山閣大飯店」旁的觀景平台，看夕陽將雲海染成金橘色，隨後在百年檜木香氣包圍的餐廳享用在地愛玉與原民風味晚餐 🍷。","coupleHighlight":"在阿里山賓館復古的露天陽台，兩人共披一條喀什米爾圍巾，啜飲一杯阿里山高山烏龍茶，看山嵐緩緩穿梭指尖 ☕"},{"day":2,"theme":"神木與鐵道・穿梭百年巨木的呢喃 🚂","morning":"睡到自然醒後享用飯店早餐，隨後搭乘「阿里山森林鐵路（沼平線至神木線）」感受復古木造車廂的輕輕搖晃，抵達神木車站 🌿。","afternoon":"漫步於「巨木群棧道（二期）」，仰望上千年的紅檜神木，並在隱身林間的「阿里山郵局」寄出一張寫給彼此未來的明信片 📮。","evening":"午後造訪全台最高海拔的咖啡館「阿里山咖啡館」或山野書店，品嚐手沖藝伎咖啡，晚餐品嚐在地鮮甜的山葵豆腐與高山高麗菜 🥢。","coupleHighlight":"在千代蓮橋旁的光影交錯處，緊牽著手聽風吹過巨木冠層的沙沙聲，留下相視而笑的溫柔側影 📸"},{"day":3,"theme":"曙光破曉・祝山雲海與浪漫告別 🌅","morning":"清晨搭乘「祝山線觀日列車」，在全台最高車站等待第一道曙光金光灑落無垠雲海，感受震撼人心的浪漫時刻 🌤️。","afternoon":"返回飯店享用悠閒早午餐，退房前順道至「阿里山車站」二樓木造觀景台，再次眺望塔山壯麗山容，帶著滿滿芬多精踏上歸途 🚗。","evening":"午後下山行經奮起湖老街，停留片刻帶一盒現烤奮起湖大飯店鐵路便當與手作草仔粿，在車上享用復古美味，結束完美旅程 🍱。","coupleHighlight":"在祝山觀日平台上，當第一縷晨曦耀眼升起時，輕輕給對方一個深情的擁抱，將雲海日出定格成永恆 💖"}],"mustTryFoods":["阿里山高山野生愛玉子手洗愛玉凍","奮起湖現烤古早味鐵路便當","阿里山在地特色山葵豆腐","阿里山高山烏龍茶與高海拔藝伎手沖咖啡"],"tips":"1. 森林鐵路祝山線車票建議於前一天下午至阿里山車站預購，以免當天向隅。2. 阿里山日夜溫差極大（夏季夜晚亦僅10-15度），請務必攜帶防風保暖外套與圍巾。3. 假日自駕車輛需注意交通管制，建議提早抵達園區停車場或選擇台灣好行專車。","generatedAt":1793468107574,"model":"gemini-3.5-flash-lite"}},{"id":"trip_taichung","name":"台中建築美學與高美濕地浪漫風車夕陽","locationName":"Taichung, Taiwan","lat":24.1477,"lng":120.6736,"minDays":2,"maxDays":3,"budget":"$","costEstimate":"~NT$3,800 - 7,500 /人","seasons":["all"],"visited":false,"tags":["#高美濕地夕陽","#台中國家歌劇院","#審計新村文創","#宮原眼科冰品","#逢甲夜市"],"description":"午後在台中國家歌劇院感受曲牆流動的光影美學，黃昏走上高美濕地木棧道赤腳看風車與天空之鏡金色倒影，夜晚在逢甲夜市大快朵頤。","itinerary":{"summary":"為 Seb 與 Lynn 打造的台中緩調美學之旅，從世界級綠意歌劇院到高美濕地波光夕陽，在流線建築與浪漫風車中，享受專屬於彼此的無憂慢時光。","targetDays":3,"pace":"relaxed","days":[{"day":1,"theme":"流線曲率・台中國家歌劇院與空中花園美學 🏛️","morning":"睡到自然醒，搭高鐵從台灣各地輕鬆南下台中。午間入住市區設計旅店，享用精緻早午餐，隨後漫步至由伊東豊雄設計的「台中國家歌劇院」，欣賞無柱曲牆的洞穴美學。","afternoon":"午後移步至歌劇院頂樓的「曲牆視聽室」與戶外「空中花園」，在流線型水泥花園中吹著微風，欣賞植物與光影交織的幾何線條，隨興找間美學咖啡館喝杯手沖咖啡。","evening":"夜幕低垂時，於歌劇院內的高空餐廳享用浪漫燭光晚餐，俯瞰七期璀璨夜景，享受被純粹美學包圍的微醺氛圍。","coupleHighlight":"傍晚在空中花園的白色曲牆邊並肩眺望落日餘暉，交換一杯彼此交換啜飲的耶加雪菲 ☕"},{"day":2,"theme":"光影詩篇・亞洲大學現代美術館與草悟道綠意 🌿","morning":"慵懶享用飯店早餐後，前往由安藤忠雄設計的「亞洲大學現代美術館」。沉浸在三角形幾何與清水混凝土交織的光影迴廊中，感受當代藝術的純粹靜謐。","afternoon":"午後轉往「草悟道」與「勤美誠品綠園道」，穿梭於巷弄間的獨立書店與質感選物店，在綠蔭大道旁的老宅咖啡館品嚐手作甜點。","evening":"晚餐造訪精誠商圈的私廚餐酒館，品嚐在地食材結合的創意料理，餐後在微涼夜色中散步於市民廣場旁。","coupleHighlight":"在安藤美術館的清水混凝土三角迴廊光影交界處，為彼此拍下第一張極簡線條的浪漫合影 📸"},{"day":3,"theme":"風車夕照・高美濕地海天一色浪漫告別 🌅","morning":"享受一個沒有鬧鐘的早晨，退房後在台中文青早午餐店享用慢食。午後乘坐專車或計程車，緩緩向海線行駛，沿途欣賞海風漸漸清晰。","afternoon":"抵達「高美濕地」，赤腳走上木棧道，看著巨大的白色風力發電機在海風中轉動，夕陽將整片天空與水面染成魔幻的粉橘與金黃色澤。","evening":"在濕地旁的景觀咖啡館小憩，一邊回味這三天的建築與夕陽記憶，一邊從容搭乘高鐵返回台灣溫暖的家。","coupleHighlight":"在夕陽沒入海平線的魔幻時刻，牽手走在木棧道的倒影中，讓巨大風車與金色波光見證彼此的深情一吻 🌅"}],"mustTryFoods":["台中國家歌劇院高空法式料理","草悟道巷弄手作戚風蛋糕與精品手沖咖啡","精誠商圈在地食材創意餐酒館料理","清水在地古早味筒仔米糕與芋頭排骨酥湯"],"tips":"台中市區景點多可透過台灣等公車App搭配YouBike 2.0移動，前往高美濕地建議傍晚前1.5小時抵達以避開人潮；美術館與熱門景觀餐廳建議提前兩週預約窗景位。","generatedAt":1793468109072,"model":"gemini-3.5-flash-lite"}},{"id":"trip_shanlinxi","name":"杉林溪水濂瀑布與黃金水杉森林秘境","locationName":"Shanlinxi, Nantou","lat":23.6331,"lng":120.7933,"minDays":2,"maxDays":3,"budget":"$","costEstimate":"~NT$8,000 - 15,000 /人","seasons":["summer","autumn","spring"],"visited":false,"tags":["#松瀧岩瀑布","#黃金水杉林","#鬱金香繡球花","#忘憂森林","#避暑芬多精"],"description":"走入負離子滿溢的松瀧岩瀑布巨石水簾洞，秋季沉醉於全台最美黃金水杉林，夏季平均20度的涼爽山風中漫步夢幻繡球花海與忘憂森林。","itinerary":{"summary":"為 Seb 與 Lynn 量身打造的南投森林系浪漫之旅，在溪頭與霧社的松林迷霧與暖心手沖咖啡香氣中，享受無拘無束的漫步時光，拾光慢旅。","targetDays":3,"pace":"relaxed","days":[{"day":1,"theme":"初見松濤・溪頭森林浴與微光漫步 🌲☕","morning":"從台灣出發驅車南投，午後抵達溪頭自然教育園區，牽手漫步於參天柳杉林間，深呼吸滿含芬多精的清新空氣。","afternoon":"造訪隱身於森林木屋中的「天井咖啡」，挑選靠窗座位，啜飲一杯在地產的蜜香紅茶與手沖咖啡，看著窗外山嵐緩緩升起。","evening":"入住溪頭附近的景觀民宿，享用以當地高山蔬菜與鱒魚烹調的溫馨晚餐，夜裡在陽台聽著蟲鳴看滿天星斗。","coupleHighlight":"在漫天霧氣的松林木棧道上，共撐一把傘，分享熱騰騰的蜜香紅茶暖手。"},{"day":2,"theme":"雲端茶香・霧起杉林間的私房對話 ☁️🍵","morning":"睡到自然醒，享用民宿的手作早餐後，緩慢驅車前往鹿谷大崙山銀杏森林，欣賞茶園與銀杏交織的翠綠山景。","afternoon":"停留「武岫農場」景觀茶坊，坐在茶園旁的戶外木棧椅，伴著雲海微風，品嘗現泡的高山烏龍茶與茶香鬆餅。","evening":"返回鹿谷市區，品嚐在地知名的竹筒飯與筍干焢肉，隨後在微涼夜風中散步回房。","coupleHighlight":"在茶園高處的觀景台，輕輕依偎著彼此，等一陣雲霧散開，看夕陽將茶樹染成溫柔的金黃色。"},{"day":3,"theme":"湖光山色・日月潭畔的慢靈魂告別 🌊🛶","morning":"慵懶退房後前往日月潭，造訪水社碼頭旁美學獨具的「Hàn-Lú 涵碧樓」或水社茶居，享用精緻早午餐，靜靜凝望湖面如鏡的波光。","afternoon":"租一輛電動單車，沿著被CNN評為全球最美自行車道之一的「水社至向山段」騎行，隨性在向山行政暨遊客中心停留，欣賞清水模建築的光影交錯。","evening":"在向山咖啡館喝一杯最後的湖畔拿鐵，帶著滿滿的松林芬多精與茶香記憶，從容開車返回台灣溫暖的家。","coupleHighlight":"在向山懸臂式觀景台的夕陽餘暉下，用拍立得為彼此拍下這趟旅程最後的甜蜜剪影。"}],"mustTryFoods":["溪頭高山竹筒飯","鹿谷在地蜜香紅茶","日月潭阿薩姆紅茶鬆餅","清蒸碧湖活魚"],"tips":"南投山區午後容易起霧且氣溫驟降，建議準備防風外套與輕便雨具；山路多彎道，租車自駕或包車請留意行車安全，並建議提前一個月預訂溪頭與日月潭的特色景觀民宿以確保住房品質。","generatedAt":1793468119255,"model":"gemini-3.5-flash-lite"}},{"id":"trip_norway","name":"挪威蓋倫格峽灣遊船與羅弗敦極光木屋","locationName":"Norway 🇳🇴","lat":62.1015,"lng":7.094,"minDays":7,"maxDays":12,"budget":"$$","costEstimate":"~NT$90,000 - 145,000 /人","seasons":["summer","winter","autumn"],"visited":false,"tags":["#蓋倫格峽灣","#羅弗敦群島","#午夜太陽","#北極光","#紅色漁屋Rorbu"],"description":"搭乘渡輪穿梭在世界遺產蓋倫格峽灣壯闊峭壁之間，夏季欣賞壯觀七姊妹瀑布與午夜太陽，冬季入住羅弗敦紅色海岸木屋仰望極光曼妙漫舞。","itinerary":{"summary":"為 Seb 與 Lynn 打造的慢活北歐浪漫之旅，從世界最美蓋倫格峽灣的碧綠水影，到羅弗敦群島極光木屋下的溫柔呢喃，在極光與峽灣間刻畫專屬於兩人的永恆詩篇。","targetDays":10,"pace":"relaxed","days":[{"day":1,"theme":"啟程・飛越亞歐大陸抵達奧斯陸 ✈️","morning":"搭乘班機由台灣出發，在機艙內並肩規劃即將展開的北歐夢幻峽灣與極光之旅 ☁️。","afternoon":"抵達奧斯陸加勒穆恩機場，搭乘機場快線 Flytoget 輕鬆前往市中心飯店辦理入住 🚆。","evening":"漫步於奧斯陸鬧區，在溫馨的北歐風餐廳享用經典肉丸與莓果醬，適應時差 🕯️。","coupleHighlight":"在異國街頭的微涼夜色中牽手散步，分享一杯熱拿鐵暖手 ☕"},{"day":2,"theme":"峽灣門戶・漫步奧斯陸海濱與雕刻公園 🌿","morning":"睡到自然醒，前往當紅的奧斯陸歌劇院（Oslo Opera House）大理石斜屋頂上眺望峽灣海景 🏛️。","afternoon":"造訪維格蘭人生雕刻公園（Vigeland Park），在綠意盎然的草地上悠閒漫步，欣賞生命之柱的藝術震撼 🌳。","evening":"於阿克爾碼頭（Aker Brygge）海濱餐廳享用新鮮肥美的挪威烤鮭魚晚餐 🐟。","coupleHighlight":"並肩坐在碼頭邊的木棧道上，看著夕陽將海面染成玫瑰金，輕輕靠著彼此的肩膀 🌅"},{"day":3,"theme":"山居歲月・奔赴世界遺產蓋倫格峽灣 🏔️","morning":"搭乘國內航班前往奧勒松（Ålesund），欣賞沿途如畫的群島風光，午後租車前往蓋倫格 🚗。","afternoon":"入住蓋倫格峽灣旁的景觀木屋，陽台正對著壯麗的群山與瀑布風景 🪟。","evening":"在木屋露台上用熱水壺煮一壺熱茶，靜靜欣賞峽灣黃昏時刻的光影變幻 🍵。","coupleHighlight":"在寂靜無聲的峽灣深谷中，兩人裹著同一條羊毛毯看星空漸漸亮起 ✨"},{"day":4,"theme":"碧水如鏡・蓋倫格峽灣浪漫遊船之旅 ⛵","morning":"睡個懶覺後緩步登船，展開「七姊妹瀑布」與「蘇格徒勞」峽灣遊船巡航，仰望千米峭壁 🌊。","afternoon":"船行至奧勒松新藝術風格小鎮，漫步於色彩繽紛的童話街道，造訪當地獨立咖啡館 ☕。","evening":"在港口邊的餐廳品嚐現撈的炙烤干貝與挪威鮮蝦料理 🦐。","coupleHighlight":"在遊船甲板頂層風最大的地方，相擁著大笑並拍下一張頭髮凌亂卻笑得最甜的合照 📸"},{"day":5,"theme":"飛向極光之境・抵達羅弗敦群島 ✈️","morning":"悠閒享用飯店早餐，驅車前往奧勒松機場，搭乘短途航班飛往羅弗敦群島門戶——勒內斯（Leknes） 🛩️。","afternoon":"領取租車，沿著有「國家景觀公路」之稱的 E10 公路，駛向海濱極光木屋（Rorbu） 🏡。","evening":"入住傳統漁民改建的紅色木屋，屋內燃燒著微溫的暖爐，窗外就是海浪聲 🔥。","coupleHighlight":"在木屋的私人海景露台上，煮一鍋熱湯，期待今晚極光的初次降臨 🌌"},{"day":6,"theme":"世界最美漁村・漢島與雷納的慢時光 🎣","morning":"自然醒後不趕行程，車行至被譽為世外桃源的漢島（Hamnøy）與雷納（Reine）拍照留念 ⛰️。","afternoon":"在雷納村落的在地咖啡館（Reine Rorbuer Cafe）歇腳，品嚐肉桂捲與手沖黑咖啡 🥐。","evening":"享用產自當地極地海域的奶油燉鱈魚湯，溫暖脾胃 🍲。","coupleHighlight":"牽手走過雷納的木造小橋，在群山與峽灣倒影中，交換一個深情的吻 💋"},{"day":7,"theme":"白色沙灘與秘境・尋找雷讷布林恩的溫柔 🏖️","morning":"睡到日上三竿，驅車前往烏克瑟訥（Haukland Beach）白色細沙海灘，踩踩冰涼的海水 🌊。","afternoon":"沿著海岸線兜風，隨性在路邊的小漁港停靠，看海鷗與漁船歸港 🚢。","evening":"返回極光木屋，親手烹煮一頓簡單而溫馨的晚餐 🍳。","coupleHighlight":"深夜時分，驚喜見到綠光在木屋上空舞動，兩人激動相擁於極光之下 🟢"},{"day":8,"theme":"維京歷史與峽灣夕陽・斯沃尔韦尔漫遊 ⚔️","morning":"睡飽後退房，沿著海岸公路北上，前往群島最大鎮斯沃尔韦尔（Svolvær），沿途欣賞奇岩怪石 🚙。","afternoon":"造訪羅弗敦維京博物館（Lofoten Viking Museum），體驗千年前北海小英雄的浪漫傳說 🏛️。","evening":"在港邊餐廳享用主廚特製的鹿肉排佐越橘醬，感受濃郁的北歐野味 🍷。","coupleHighlight":"在海邊的木造桑拿房（Sauna）體驗冰火交融，隨後赤腳跑向微涼的海風中大笑 🧖‍♀️"},{"day":9,"theme":"告別極光島嶼・重回奧斯陸文藝懷抱 🏙️","morning":"在羅弗敦的晨光中享用最後的悠閒早餐，前往機場搭機返回奧斯陸 ✈️。","afternoon":"入住奧斯陸市中心設計酒店，午後漫步於卡爾約翰門大街（Karl Johans gate），挑選精緻的北歐伴手禮 🎁。","evening":"在米其林推薦的挪威當代餐廳，享受此行最後一場精緻的雙人燭光晚餐 🍾。","coupleHighlight":"在燭光與微醺中回顧這十天的點滴，輕聲向彼此表達感謝與愛意 🥂"},{"day":10,"theme":"珍重再見・帶著滿滿極光回憶返航台灣 🧳","morning":"悠閒享用豐盛的北歐早午餐，把握最後時光在飯店附近的設計小店散步 ☕。","afternoon":"搭乘機場快線前往奧斯陸機場，辦理退稅與登機手續 ✈️。","evening":"搭乘班機啟程返回台灣，帶著滿心浪漫與極光回憶入眠 🌙。","coupleHighlight":"在飛機起飛時緊緊握著彼此的手，約定下一次的極地冒險 🤝"}],"mustTryFoods":["挪威煙燻鮭魚佐法式芥末醬 (Smoked Salmon)","羅弗敦極地奶油鱈魚湯 (Bacalao / Fiskesuppe)","北歐肉桂捲與手沖咖啡 (Kanelboller)","傳統鹿肉排佐越橘醬 (Reindeer Steak with Lingonberry)"],"tips":"1. 台灣旅客前往挪威免簽證，建議提前在台灣換好少量挪威克朗（NOK），但多數地方皆可信用卡消費。\n2. 羅弗敦群島天氣多變，極光木屋（Rorbu）與蓋倫格峽灣景觀房務必於半年前完成預訂。\n3. 行李務必攜帶防風防水外套、保暖發熱衣、防滑健行鞋與相機三腳架（拍攝極光必備）。","generatedAt":1793468129465,"model":"gemini-3.5-flash-lite"}},{"id":"trip_iceland","name":"冰島一號公路自駕與藍湖溫泉極光之旅","locationName":"Iceland 🇮🇸","lat":64.1466,"lng":-21.9426,"minDays":8,"maxDays":12,"budget":"$$","costEstimate":"~NT$95,000 - 155,000 /人","seasons":["winter","summer","autumn"],"visited":false,"tags":["#藍湖溫泉","#黑沙灘","#一號公路自駕","#瓦特納冰川健行","#極光獵捕"],"description":"在夢幻乳藍色的藍湖溫泉中享受泥膜與暖意，自駕一號公路探訪壯麗塞里雅蘭瀑布與黑沙灘，穿上冰爪漫步藍冰洞與瓦特納冰川，夜宿玻璃木屋看極光跳動。","itinerary":{"summary":"為 Seb 與 Lynn 量身打造的冰島漫旅，沿著一號公路緩行，在極光舞動的夜空下、藍湖溫泉的氤氳水氣中，牽手寫下專屬於兩人的北極圈浪漫詩篇。","targetDays":10,"pace":"relaxed","days":[{"day":1,"theme":"抵達冰島・雷克雅維克漫步與溫暖咖啡香 ☕","morning":"搭乘班機抵達凱夫拉維克國際機場，租車後緩緩駛入首都，入住市區精緻設計旅店稍作時差調整。","afternoon":"午後漫步於彩色鐵皮屋林立的勒加維格購物街，造訪當地知名烘焙坊 Brauð & Co，品嚐剛出爐、肉桂香氣四溢的肉桂捲。","evening":"在港口旁的 Kol Restaurant 享用結合冰島在地食材的精緻晚餐，品嚐鮮甜的北極蝦與冰島羊肉。","coupleHighlight":"在微涼空氣中，兩人共用一杯熱拿鐵，並肩欣賞太陽航海者雕塑背後的大海與雪山夕陽 🌅"},{"day":2,"theme":"黃金圈慢旅・瀑布與地熱谷的冰火交融 🌋","morning":"睡到自然醒後出發，前往辛格韋利爾國家公園，漫步於歐亞與北美兩大板塊交會的壯麗裂谷中。","afternoon":"前往氣勢磅礴的黃金瀑布（Gullfoss），感受水氣在陽光下折射出的雙道彩虹，隨後至 Haukadalur 地熱谷欣賞 Strokkur 間歇泉噴發的震撼瞬間。","evening":"入住黃金圈附近的質感景觀木屋，遠離光害，靜靜等待夜幕低垂。","coupleHighlight":"深夜裹著羊毛毯坐在木屋露臺，喝著熱可可，抬頭驚喜見到綠色極光在夜空中溫柔舞動 ✨"},{"day":3,"theme":"南岸奇景・黑沙灘與神祕海蝕洞 🖤","morning":"沿著一號公路南下，造訪如詩如畫的水濂洞瀑布（Seljalandsfoss），牽手走入瀑布水簾的後方，聆聽水流呢喃。","afternoon":"探訪壯麗的斯科加瀑布（Skógafoss），接著前往維克小鎮的雷尼斯黑沙灘（Reynisfjara），遠眺神秘的玄武岩柱與海上怪石。","evening":"入住維克小鎮的溫馨海景旅店，於當地餐館享用熱騰騰的冰島龍蝦濃湯。","coupleHighlight":"在黑色火山沙灘上留下兩人的腳印，任由大西洋海風吹亂髮絲，緊緊相擁取暖 🌊"},{"day":4,"theme":"冰川奇緣・瓦特納冰川與傑古沙龍冰河湖 🧊","morning":"行駛於壯闊的南岸公路，沿途欣賞無垠的苔原與遠方冰川，感受大自然的純粹與浩瀚。","afternoon":"抵達傑古沙龍冰河湖（Jökulsárlón），看著巨大的藍冰塊在湖面上靜靜漂浮，隨後漫步至一旁的鑽石沙灘，拾起被海浪推上岸、閃爍如鑽石般的碎冰。","evening":"入住赫本鎮（Höfn）附近的小木屋，享用聞名遐邇的冰島鮮甜 langoustine 龍蝦大餐。","coupleHighlight":"在冰河湖畔的浮冰旁，安靜地依偎著彼此，傾聽冰塊碎裂落水的清脆神祕聲響 🧊"},{"day":5,"theme":"東峽灣秘境・遺世獨立的小漁村 ⛵","morning":"晨光中出發，挑戰東峽灣蜿蜒卻風景絕美的濱海公路，沿途欣賞冰島最古老的流紋岩山脈。","afternoon":"停留童話般的彩虹小鎮塞濟斯菲厄汝（Seyðisfjörður），造訪藍色小教堂，並在當地極具文藝氣息的 Skaftfell 藝廊咖啡館享用手沖咖啡。","evening":"入住峽灣深處的寧靜民宿，窗外即是倒映著雪山的峽灣海景。","coupleHighlight":"在安靜的小鎮街道上散步，沒有喧囂，只有彼此的呼吸聲與踩在石子路上的沙沙聲 🍂"},{"day":6,"theme":"北方大地・米湖溫泉的極致放鬆 ♨️","morning":"驅車前往冰島北部，途經壯觀的眾神瀑布（Goðafoss），感受北國大地的粗獷之美。","afternoon":"抵達米湖地區，探索地熱區如月球表面般的 Námaskarð 沸騰泥漿池與蒸汽孔。","evening":"入住米湖畔設計旅館，晚餐後前往米湖天然溫泉（Mývatn Nature Baths）。","coupleHighlight":"在冒著白煙的乳藍色溫泉水中，兩人手握著冰涼啤酒，仰望滿天繁星與偶爾劃過天際的極光 🌌"},{"day":7,"theme":"北方首都・阿克雷里的文藝慢時光 ☕","morning":"悠閒享用早餐後，前往冰島第二大城阿克雷里，參觀建築造型獨特的阿克雷里大教堂。","afternoon":"在當地知名咖啡烘焙坊 Bláa Kannan Café 挑選靠窗座位，品嚐手工蛋糕，享受午後的溫暖時光。","evening":"漫步至艾于亞峽灣（Eyjafjörður）岸邊，欣賞小鎮點燈後的溫馨夜景，並於 strikið 餐廳享用景觀晚餐。","coupleHighlight":"在心型紅燈號誌的街道前合影，許下攜手漫步世界每一個角落的浪漫承諾 ❤️"},{"day":8,"theme":"西部荒野・斯奈山半島的魔幻山海 ⛰️","morning":"展開長途車程返回西部，前往被譽為「冰島縮影」的斯奈山半島，造訪標誌性的教會山（Kirkjufell）。","afternoon":"探訪阿爾納斯塔皮（Arnarstapi）的奇特海蝕拱門與玄武岩懸崖，感受大自然的鬼斧神工。","evening":"入住半島上的質感海景度假屋，親自下廚用當地食材烹煮一頓溫馨的燭光晚餐。","coupleHighlight":"坐在落地窗前一邊啜飲冰島冰酒，一邊靜靜觀賞教會山在夜色與極光襯托下的神祕輪廓 🍷"},{"day":9,"theme":"重返首都・療癒藍湖溫泉與浪漫告別晚餐 💧","morning":"悠閒告別斯奈山半島，驅車前往西南部，朝思暮想的世界奇景藍湖溫泉（Blue Lagoon）。","afternoon":"沉浸在富含矽藻的乳藍色溫泉中，敷上一層天然火山泥面膜，讓身心靈在溫熱泉水中徹底放鬆。","evening":"返回雷克雅維克，於頂級餐廳 Dill 享用精緻的米其林北歐創意料理，為旅程完美收尾。","coupleHighlight":"在藍湖中輕輕擁著彼此，交換這幾天在極光下累積的感動與悄悄話 💭"},{"day":10,"theme":"溫馨返程・帶著北歐微光回台灣 ✈️","morning":"在雷克雅維克人氣咖啡館 Reynir Bakery 品嚐最後一頓北歐早午餐，隨後採買高品質的冰島羊毛織品與魚子醬伴手禮。","afternoon":"前往凱夫拉維克國際機場，還車並辦理登機手續，搭乘班機滿載美好回憶踏上歸途。","evening":"航班飛行中，回憶這十天冰島的冰川、極光與溫泉。","coupleHighlight":"在飛機舷窗邊緊握著彼此的手，回味兩人一起在世界盡頭追逐極光的永恆浪漫 💍"}],"mustTryFoods":["冰島傳統羊肉湯 (Kjötsúpa)","冰島小龍蝦/海螯蝦 (Langoustine)","經典肉桂捲 (Kanill – Brauð & Co)","極鮮北極汪洋魘魚與地產海鮮料理"],"tips":"1. 冰島天氣多變，一號公路自駕強烈建議租用四輪驅動（4x4）車輛，並務必加保風沙險（SAAP）。\n2. 藍湖溫泉（Blue Lagoon）與熱門餐廳如 Dill 需至少提前兩個月官網預約。\n3. 冬季極光之旅保暖衣物首重防風防水的極地外套、雪靴以及防滑冰爪。","generatedAt":1793468128820,"model":"gemini-3.5-flash-lite"}},{"id":"trip_turkey","name":"土耳其卡帕多奇亞熱氣球與棉堡歐亞漫遊","locationName":"Türkiye 🇹🇷","lat":38.6431,"lng":34.8289,"minDays":7,"maxDays":10,"budget":"$$","costEstimate":"~NT$58,000 - 92,000 /人","seasons":["spring","autumn","summer"],"visited":false,"tags":["#卡帕多奇亞熱氣球","#洞穴飯店","#棉堡石灰棚","#博斯普魯斯海峽","#藍色清真寺"],"description":"清晨在卡帕多奇亞奇岩峽谷上空隨百顆熱氣球緩緩升空迎接第一道曙光，入住百年洞穴Villa，光腳漫步棉堡雪白石灰棚溫泉，在伊斯坦堡博斯普魯斯海峽遊船跨越歐亞兩洲。","itinerary":{"summary":"以土耳其蔚藍海岸的蔚藍海潮與柑橘花香為譜，為Seb與Lynn奏一曲慵懶而深情的12日浪漫雙重奏，在琴鍵般的古城石階與地中海夕陽中共度餘生。","targetDays":12,"pace":"relaxed","days":[{"day":1,"theme":"抵達歐亞交界・博斯普魯斯海峽的浪漫初見 ✈️","morning":"搭乘長榮航空由台北直飛伊斯坦堡，在機上享用雙人早餐，遠眺窗外漸次變化的歐亞大陸地形。","afternoon":"入住位在加拉塔（Galata）區的奢華設計酒店，慵懶地換上輕便服裝，在房間內享用迎賓土耳其紅茶與開心果軟糖。","evening":"漫步至加拉塔石塔旁的老街，在充滿文藝氣息的Café Privato享用漫長而溫馨的雙人晚餐，品嚐傳統砂鍋料理。","coupleHighlight":"牽手登上加拉塔觀景台，在金角灣落日餘暉下，聽著街頭藝人的手風琴合奏，許下旅行的第一個願望 🎶"},{"day":2,"theme":"藍色清真寺與私房海峽午茶 🕌","morning":"睡到自然醒，享用豐富的土耳其慢活早午餐。隨後前往蘇丹艾哈邁德區，欣賞藍色清真寺（蘇丹艾哈邁德清真寺）的壯麗藍色伊茲尼克磁磚。","afternoon":"搭乘私人包租遊船，手持土耳其產區白酒，悠閒航行於博斯普魯斯海峽，看兩岸鄂圖曼木造別墅與歐亞大橋交錯。","evening":"在海峽畔的Palace Restaurant享用精緻海鮮晚餐，微風中夾雜著愛琴海的鹹香。","coupleHighlight":"在遊船的船頭相依偎，用相機記錄下雙雙飛過的海鷗與夕陽染紅的鄂圖曼宮殿剪影 🥂"},{"day":3,"theme":"飛越月球地貌・卡帕多奇亞的地下浪漫 🎈","morning":"搭乘國內線班機前往卡帕多奇亞。入住由百年洞穴改建的精緻奢華飯店Museum Hotel，在露台眺望奇岩怪石。","afternoon":"參觀果里美露天博物館（Göreme Open-Air Museum），牽手探索藏在岩壁中的古老拜占庭壁畫與教堂。","evening":"在洞穴餐廳Seten Anatolian Cuisine享用慢火燉煮的陶罐料理，搭配當地特產紅酒。","coupleHighlight":"深夜在洞穴房間的私人陽台，裹著毛毯並肩數星星，感受火山奇岩帶來的神祕靜謐 ✨"},{"day":4,"theme":"熱氣球晨曦與玫瑰谷夕陽 🌄","morning":"黎明前夕在專屬陽台觀賞滿天色彩繽紛的熱氣球緩緩升空，隨後享用精緻的有機土耳其早餐。","afternoon":"午後租一台復古Vespa或包車前往玫瑰谷（Rose Valley），在粉紅色的奇岩山徑間輕輕漫步。","evening":"坐在谷底的隱密咖啡座，點一壺熱蘋果茶，靜靜等待夕陽將整片奇岩染成浪漫的玫瑰金色。","coupleHighlight":"在玫瑰谷的夕陽至高點，兩人分享一塊剛出爐的土耳其芝麻圈（Simit），交換彼此眼中的溫柔笑意 🥨"},{"day":5,"theme":"地中海蔚藍序曲・安塔利亞老城漫步 🍊","morning":"搭機飛往地中海度假勝地安塔利亞。入住老城卡雷奇（Kaleiçi）內隱密的花園精品飯店，被滿園的柑橘樹香氣包圍。","afternoon":"午後在老城鋪滿鵝卵石的狹窄巷弄中隨性漫步，探訪奧斯曼時期的古老木造宅邸與精緻地毯小店。","evening":"在崖邊餐廳Vanilla Restaurant享用結合地中海與安那托利亞風味的精緻燭光晚餐。","coupleHighlight":"在哈德良門（Hadrian's Gate）前輕輕擊掌，隨後在老城巷弄的一家獨立黑膠唱片咖啡館共聽一張老爵士黑膠 🎹"},{"day":6,"theme":"杜登瀑布與地中海蔚藍海岸的慵懶午後 🌊","morning":"睡到日上三竿，在飯店花園享用現榨的安塔利亞甜橙汁與土耳其起司拼盤。","afternoon":"前往杜登瀑布（Lower Düden Waterfall），看壯麗的水幕直接奔騰注入蔚藍的地中海懷抱。","evening":"返回老城港口，挑選一家臨海露天酒館，品嚐現撈的地中海鮮魚與冰涼的土耳其生啤酒（Efes）。","coupleHighlight":"坐在港邊的木棧板上，讓雙腳懸空輕晃，任由地中海的鹹濕海風吹亂兩人的髮絲 🌊"},{"day":7,"theme":"費特希耶・蝴蝶谷的藍色琴鍵與隱密海灣 🦋","morning":"沿著土耳其最美的D400濱海公路自駕前往費特希耶，沿途盡是懸崖與蔚藍海岸線的絕景。","afternoon":"包下一艘私人的木造古船（Gulet），駛向僅能由水路抵達的蝴蝶谷（Butterfly Valley），在私密海灣游泳。","evening":"入住奧呂代尼茲（Ölüdeniz）海灘旁的奢華度假村，在私人陽台上欣賞地中海的滿天星斗。","coupleHighlight":"在私人包船的甲板上，躺在日光浴墊上互相塗抹防曬乳，隨後手牽手跳入清澈見底的藍綠色海水中 ⛵"},{"day":8,"theme":"死海滑翔翼與藍色潟湖的浪漫驚嘆 🪂","morning":"清晨在奧呂代尼茲平靜如鏡的藍色潟湖（Blue Lagoon）畔散步，享用豐盛的歐陸早午餐。","afternoon":"若想挑戰自我，可體驗雙人滑翔翼（Tandem Paragliding）自巴巴達山躍下，從雲端俯瞰世界最美的海灘弧線。","evening":"在海灘邊的Secret Garden餐廳，伴隨現場吉他彈唱，享用炭烤羊排與土耳其茴香酒（Raki）。","coupleHighlight":"在滑翔翼降落後，互相擁抱慶祝征服高空，並在海灘邊共飲一杯冰涼的石榴汁慶祝勇敢的冒險 🍹"},{"day":9,"theme":"愛琴海的白色詩篇・博德魯姆風車山丘 🤍","morning":"沿著蔚藍海岸繼續北上，前往愛琴海邊的白色山城博德魯姆（Bodrum）。入住崖邊的Mandarin Oriental極奢度假村。","afternoon":"參觀博德魯姆城堡與水下考古博物館，隨後漫步於漆成全白的巷弄，欣賞窗台垂掛的九重葛。","evening":"在港口邊的Orfoz Restaurant享用精緻的愛琴海生蠔與白酒，享受極致奢華的慢食體驗。","coupleHighlight":"黃昏時分，並肩坐在山丘上的古風車遺跡旁，看夕陽將博德魯姆的白色房屋與愛琴海染成一片溫柔的蜜桃色 🌅"},{"day":10,"theme":"愛琴海私人海灘・橘園裡的雙人午后 🍊","morning":"完全不設鬧鐘的早晨。在度假村的私人海灘躺椅上閱讀、聽音樂、享受地中海溫暖的陽光。","afternoon":"租一輛敞篷車前往半島內陸的柑橘園，在百年樹蔭下參加私人品茶與柑橘果醬手作體驗。","evening":"在度假村的無邊際水上餐廳享用浪漫燭光晚餐，聽著海浪拍打岸邊的節奏。","coupleHighlight":"在柑橘樹下親手摘下一顆甜橙，剝給對方吃，讓酸甜的果香成為這趟旅程中最甜美的味覺記憶 🍊"},{"day":11,"theme":"重返伊斯坦堡・香料市集的最後浪漫採買 🛍️","morning":"搭乘國內線班機返回伊斯坦堡。入住貝伊奧盧區的經典歷史飯店Pera Palace Hotel，感受百年流金歲月的浪漫。","afternoon":"悠閒逛一逛香料市集（Spice Bazaar），挑選頂級的番紅花、土耳其玫瑰水與手工果茶作為伴手禮。","evening":"在傳奇的Orient Express餐廳享用最後的告別晚餐，回味這12天點點滴滴。","coupleHighlight":"在歷史悠久的Pera Palace古典電梯前合影，彷彿一同穿越時空，回到鄂圖曼帝國的浪漫年代 🗝️"},{"day":12,"theme":"最後的土耳其咖啡與甜蜜歸途 ☕","morning":"在飯店典雅的挑高餐廳享用最後一頓豐盛的土耳其早餐，並在街角小店細細品嚐一杯正統的土耳其咖啡。","afternoon":"帶著滿滿的柑橘香氣與海風回憶，搭乘專車前往伊斯坦堡機場，準備搭乘長榮航空直飛班機返回台北。","evening":"在飛機上舒適地入眠，夢見博斯普魯斯海峽的波光與卡帕多奇亞的熱氣球。","coupleHighlight":"在機場入關前，交換一封這幾天趁對方睡著時偷偷寫下的手寫信，為這趟蔚藍海岸之旅劃下完美句點 💌"}],"mustTryFoods":["土耳其砂鍋陶罐料理 (Testi Kebabı)","安塔利亞鮮榨甜橙汁與柑橘甜點","愛琴海炭烤鮮魚與Meze前菜拼盤","傳統土耳其芝麻圈 (Simit) 配紅茶"],"tips":"1. 台灣旅客前往土耳其觀光享有電子簽證（e-Visa）便利免簽證費優惠，出發前務必線上申辦。 2. 蔚藍海岸與地中海自駕建議選擇D400公路，風景絕美但山路彎曲，建議租借自排車並購買全險。 3. 建議攜帶輕便防風外套與太陽眼鏡，因地中海與山區日夜溫差較大，且防曬至關重要。","generatedAt":1793468155204,"model":"gemini-3.5-flash-lite"}},{"id":"trip_matsu","name":"馬祖藍眼淚銀河浪花與芹壁石屋慢活","locationName":"Matsu, Taiwan","lat":26.1558,"lng":119.9289,"minDays":3,"maxDays":4,"budget":"$","costEstimate":"~NT$10,500 - 18,500 /人","seasons":["spring","summer","autumn"],"visited":false,"tags":["#馬祖藍眼淚","#北竿芹壁聚落","#八八坑道老酒","#東引國之北疆","#踩星沙夜航"],"description":"春夏夜晚在海灣尋訪如阿凡達銀河般夢幻的藍眼淚螢光浪潮，漫步依山傍海的北竿芹壁花崗岩石頭屋享受「馬祖地中海」咖啡時光，在八八坑道酒香中細品甘醇老酒。","itinerary":{"summary":"為 Seb 與 Lynn 量身打造的馬祖慢活之旅，在閩東石屋的夕陽與蔚藍海岸的藍眼淚中，牽手共譜浪漫的海島詩篇。","targetDays":4,"pace":"relaxed","days":[{"day":1,"theme":"抵達南竿・貝殼沙灘與微醺海風 🌊","morning":"從台灣搭乘早班機飛抵南竿機場，由民宿專車溫柔接送，前往馬祖村稍作休憩，適應島嶼的緩慢步調。","afternoon":"漫步至津沙聚落，在百年石屋間的小徑探險，隨後於海景咖啡館點兩杯手沖咖啡，靜靜聆聽浪濤聲。 ☕","evening":"在南竿聚落享用道地的老酒麵線與紅糟炒飯，餐後漫步到沙灘邊，碰觸夜晚微微發光的藍眼淚奇景。 💙","coupleHighlight":"在津沙海灘的夜色下，兩人依偎著赤腳踩在細沙上，尋找浪花拍打時泛起的點點藍色螢光。"},{"day":2,"theme":"北竿芹壁・地中海石屋與山城夕陽 🏰","morning":"睡到自然醒後，搭乘下午前的小三通交通船前往北竿，入住芹壁村的經典面海石屋民宿。","afternoon":"坐在「芹壁天后宮」旁的觀景茶屋，點一壺馬祖高梁奶茶，遠眺龜島，看陽光灑落層疊的石頭屋。","evening":"在芹壁唯一的地中海風情餐廳享用晚餐，伴隨窗外漸漸暗去的寧靜海灣與漁火。 🍷","coupleHighlight":"黃昏時分，坐在石屋的窗檯邊並肩看夕陽染紅整片海灣，手握著彼此共享一杯溫熱的熱可可。"},{"day":3,"theme":"大坵尋鹿・梅花鹿島嶼的溫柔漫步 🦌","morning":"搭乘專屬小船前往無人島大坵，沿著環島步道漫步，享受被野生梅花鹿包圍的療癒時光。","afternoon":"返回北竿後，午後在橋仔聚落的漁村小店品嚐古早味魚麵，感受舊時漁業風華的寧靜。","evening":"夜宿芹壁，參加在地嚮導帶領的夜間藍眼淚生態探索，遠離光害欣賞滿天銀河星空。 ✨","coupleHighlight":"在無人島的草坡上，兩人屏息輕輕餵食溫馴的梅花鹿，相視而笑享受只屬於彼此的世外桃源。"},{"day":4,"theme":"島嶼告別・馬祖老酒香氣的依戀 🍶","morning":"在石屋民宿的陽台上享用豐盛早餐，最後一次慵懶地俯瞰芹壁的湛藍海景與龜島。","afternoon":"搭機返回台灣前，前往南竿八八坑道參觀窖藏老酒，並在馬祖酒廠挑選一瓶紀念兩人的專屬陳高。 🍾","evening":"帶著滿滿的海島記憶與相機裡的浪漫合照，搭乘班機平安返回溫暖的台灣。","coupleHighlight":"在八八坑道濃郁的酒香中，兩人勾著手指約定好，未來還要再來馬祖看一次銀河與藍眼淚。"}],"mustTryFoods":["老酒麵線","紅糟鰻魚","地中海風味淡菜","魚餃湯"],"tips":"1. 馬祖地形起伏大且多霧，建議租借機車或預約民宿接駁，並隨身攜帶暈船藥。2. 追逐藍眼淚最佳季節為4至6月，需避開農曆滿月前後光害最強的日期。3. 跳島船班受天候影響大，行程彈性放鬆為上策。","generatedAt":1793468158189,"model":"gemini-3.5-flash-lite"}}];

